        "name": "悪ー魂喰らいの呪怨",
        "text": "効果：\n・敵一体を攻撃し、３６０％ダメージを与える。\n・目標が１％の減傷を持っているごとに、芦屋道満は「恨み」効果を１層獲得する。\n『用語』\n恨み：\n・「恨み」効果１層ごとに、自身の増傷＋１％。\n・効果は2ターン持続し、最大５０層まで重ね合わせ可能、解除不可。\nポイント：\n敵の減傷の高さによって自身の増傷が上がる点が強力です。"
