        "text": "効果：\n・敵全体に攻撃し、２４０％のダメージを与える。\n・奥義は「光なき琥珀」を所持する目標に対し、追加でダメージの２０％分の「黒血侵食」効果を付与する。\n・さらに敵側で「光なき琥珀」を所持する全目標に、「光なき琥珀」効果を１層付与する。\n・奥義攻撃で目標を倒した時、オベロンはすぐに戦意を１０００点回復する。\nポイント：\n・奥義攻撃で敵を倒した場合にオベロンがすぐに戦意を１０００点回復できる点がとても強力です。\n・光なき琥珀を持っている敵に対して光なき琥珀を追加で与え、黒血浸食を与えれる点が強力です。"
