        "text": "＊ここはUR時との違いはありません。\n『用語』\n悪夢のエネルギー：スキルの欄に記載。\nポイント：\n・致命的なダメージを受けた場合に１回復活し耐久面が永続的に強化される点がとても強力です。\n・HPが一定値以下になるとスキルで反撃できる点が強力です。\n・パッシブで自身の減傷とスキル確率を大幅に上げれる点が強力です。\n・条件はありますが味方全体を回復できる点が強力です。"
