        "text": "UR時との違い：\n・敵を攻撃する威力が３００％から３６０％にアップしています。\n・範囲攻撃を与える範囲が前回の奥義／超奥義で命中したキャラに拡大されました。\n・範囲ダメージの威力が３０％から１００％にアップしています。\n・眩暈にする確率が１５％から４０％にアップしています。\n『用語』\n眩暈：\n・行動不可。\n・効果は１ターン継続、重ね掛け不可。\nポイント：\n・複数の敵を行動不能に出来る可能性がある点が強力です。\n・条件次第で周りの敵にもダメージを与えれる点が優秀です。"
