    "skills": {
      "normal": {
        "name": "真・神の鞭ー颶風",
        "text": "効果：\n・敵1体に３００％のダメージを与える。\n・自身のスキルダメージを２ターンの間＋３０％するとともに、攻撃した敵の戦意回復速度を２ターンの間ー２０％する。どちらも解除不可。\n・「風の束縛」を付けた敵に５０％のダメージを与える。\n風の束縛：目標の敵を１ターン行動不能にする。\nポイント：\nスキルダメージアップの効果と敵の戦意回復速度減少が地味ながらいい働きです。"
      },
      "passive": {
        "name": "神の鞭－覚",
        "text": "効果：\n・自身のスキル減傷＋２０％、奥義減傷＋２０％、増傷＋１０％、減傷＋１０％、風の束縛を免疫できる。\n・同行キャラは増傷を＋１０％（解除不可）、自身は同行キャラの中で増傷が一番高いキャラの増傷の１０％分を獲得。\n・もし目の前に味方がいる場合、当該キャラの減少の１０％分を自身が獲得し、当該キャラは自身のコントロール抵抗の１０％分を獲得する。このバフは味方のターン開始時にリセットされる。\n・自身が後列にいる或いは味方のキャラが1名しかいない場合、「そよ風の守護」を発動する。\nそよ風の守護：\n・敵キャラの攻撃を受けると４０％の確率でその敵に「風の束縛」をかける。（攻撃を受けた時、自身HPが３５％以下で「嵐の目」を持っている場合、この確率は６０％になる。）この効果で３回以上「風の束縛」をかけられた敵は戦闘終了まで防御力ー３０％\n・「風の束縛」が発動成功するごとに、自身コントロール抵抗率＋５％（最大50％まで）、コントロール率＋２.５％（最大25％まで）アップする。\n・自身は、最大３つの敵に「風の束縛」をかけることが可能。上限数を超えるごとに、最初の「風の束縛」が解け、その敵の戦意を２００点吸収し、自身の次の奥義のダメージ＋１０％（最大５０％まで）になる。\n嵐の目：\n・自身が二人の敵に「風の束縛」をかけるごとに、「嵐の目」を１つ獲得する。（ターン毎に２回まで発動でき、最大１０個保持できる）\n・「嵐の目」を１つ持つごとに、２ターンの間、自身奥義ダメージ＋５％、減傷＋５％。解除不可。\nポイント：\n無条件で、自身の減傷などを大きく上げることが出来る点が強力です。\n自身が後列にいる場合、一定の確率で、敵を行動不能にできる点がかなり強力です。\nまた、自身のステータスを一時的に上げれる点、条件次第で敵の防御力をー３０％出来る点も便利です。"
      },
      "ultimate": {
        "name": "風のエルフー群星の墜落",
        "text": "効果：\n・敵1体に５００％のダメージを与え、目標の上下左右の敵に８０％のダメージを与える。このとき、目標の減傷率を３０％無視できる。\n・５０％の確率で「風の束縛」をかける。この「風の束縛」は次に攻撃を受けると解除され、戦意を２００点減少する。\n・コントロールされた全ての敵に最大HPの５％相当の追加ダメージを与える。\n・２ターンの間、攻撃力＋１０％、ダメージ率＋１０％、コントロール率＋１０％、会心率＋１０％、防御＋３０％。\n・自身にかかっているスキルをリセットし、再適用する。\nポイント：\n目標に減傷率３０％を無視しての大ダメージを与える点がとにかく強力です。\nまた、一時的にですが５０％の確率で行動不能にできる点も便利ですし、自身の攻防のステータスアップ出来る点も良いです。"
      },
      "evolution": {
        "fire": [
          "Lv1: 嵐の目\n効果：スキル（真・神の鞭ー颶風）に以下の効果を追加する。\n・自身最大HPの５％と２００点の戦意を回復する。\n・スキルを発動する時、自身の戦意が満タンで、６つ以上の「嵐の目」を持っている場合、全部の戦意を消費して奥義をもって追加攻撃する。\nポイント：\n条件付きですが、スキル攻撃の後に奥義を撃てるのは強いと思います。\nまた少しですがHP回復する点もありがたいです。",
          "Lv2: 嵐のうなり\n効果：パッシブ（神の鞭－覚）に以下の効果を追加する。\n・コントロール率＋２０％、コントロール抵抗率＋２０％。\n・登場時「嵐の目」を２つ獲得する。\n・登場から２ターンの間、敵一人から受ける合計ダメージは自身の最大HPの２５％を超えない。\n・ターン毎の味方の戦意の変化（増減）を記録し、３００点の戦意ごとに、自身の次の奥義（追撃と反撃は発動不可）を発動すると、味方の攻撃力が１番高いキャラに奥義ダメージ＋０.５％、味方の防御力が一番高いキャラに減傷＋０.５％（最大１５％までで、効果１ターンで解除不可、ターン毎に１回のみ）\n・自身のコントロール率とコントロール抵抗率の合計がその敵のコントロール率とコントロール抵抗率の合計より高い場合、そのダメージを３０％カット。\nポイント：\nただでさえ強かったパッシブにコントロール率・抵抗率が追加され、このおかげで高い頻度でダメージを３０％カットできる点がとても強力です。\n登場から２ターンの間、ダメージを一定値に抑えられる点も戦闘不能になりづらい点が強力です。\n味方へのバフもありがたいです。",
          "Lv3: 颶風の怒り\n効果：奥義（風のエルフー群星の墜落）に以下の効果を追加する。\n・コントロールされた味方一人の全てのデバフを解除する。\n・「嵐の目」を１つ持つごとに、２ターンの間、自身の減傷＋１０％、増傷＋５％。解除不可。\n・累計で「嵐の目」を６つ獲得するごとに、奥義が「颶風の怒り」に入れ替わる。発動後、全ての「嵐の目」は消費される。\n・自身の奥義は５０％「黒血侵食」を付ける。\n黒血侵食：目標に与えたダメージの一定割合の最大HPを減少させる、デバフ解除では解除できない。\n颶風の怒り：敵全体に２５０％のダメージを与える。そして、「風の束縛」がかかった人数分（最大２まで）「嵐の目」を獲得する。\n他の効果は入れ替わる前の奥義と同じ。\nポイント：\n条件付きですが、敵全体に２５０％ダメージが強力です。全体攻撃のダメージ倍率としてはこれまでのキャラで1番高いです。\n与えたダメージの５０％の黒血侵食という点や、コントロールされた味方1体のデバフを全て解除できる点も強いです。"
        ],
        "ice": []
      }
    },
