    "skills": {
      "normal": {
        "name": "五芒星の陣・覚",
        "text": "効果：\n・敵単体に２６０％のダメージを与え、さらに１５０点の戦意を回復する。\n・スキルの発動率が１０％アップする。（３回まで累積し、戦闘終了まで継続）\n・初回のスキルは必ず「冥鳥」を発動する。\n『用語』\n冥鳥：\n・２ターンの間、破撃＋２０％、コントロール＋２０％、解除可能。\n・目標の後列の敵にも８０％分のダメージを与える。（このダメージによる戦意回復はなし）\n・４０％の確率で命中した全ての目標を「麻痺」にする。\n・このスキルが与えた合計ダメージの３０％分のHPを回復し、次のスキルを「天狗」に切り替える。\n天狗：\n・２ターンの間、会心＋２０％、生命吸収＋２０％、解除可能。\n・目標周り（上下左右）の敵に４０％のダメージを与え、このスキルが与えたダメージは４０％アップする。\n・戦意を１５０点回復し、次のスキルを「冥鳥」に切り替える。\n麻痺：１ターンの間、行動不能。\nポイント：\n敵単体にダメージを与えつつ、周囲の敵にもダメージを与え、さらに戦意も回復できるのが便利です。\n冥鳥は複数体の行動不能を狙いやすく、HPも結構回復できる点が強力です。\n天狗は広範囲の敵を攻撃しつつ、戦意をさらに回復できる点が強いです。"
      },
      "passive": {
        "name": "陰陽師・覚",
        "text": "効果：\n・味方のターンが始まるたび、自身とランダムで戦意がMaxでない味方キャラ１体にそれぞれ１００点の戦意を回復する。\n・味方のターンが終わるたび、自身のHPを（攻撃力×戦場に残る全ての人数×２％）回復し、その半分を周り（上下左右）の味方キャラにそれぞれ回復する。\n・味方の各先発キャラが初めて倒されるとき、その意思を継承する。（増傷＋５％、減傷＋５％、累積可能で、HPを１０％回復し、倒されたキャラの残り戦意の５０％を継承する）\n・致死攻撃を受けても死亡せず、即座に全てのデバフを解除し、HPを５０％と３００点の戦意を回復する。（１戦闘につき１回のみ）\nポイント：\n味方のターン毎に、自身と味方に戦意の回復とHPを回復できる点がとにかく強力です。\nまた、1回死亡を回避出来るのも強いです。\n他には、味方が倒されたときにステータスアップとHP回復できる点も便利です。"
      },
      "ultimate": {
        "name": "絶道陰陽・幽冥白狐・平安",
        "text": "効果：\n・敵全体に２００％分のダメージを与え、命中した目標が少ないほどダメージが増加し、最大１００％まで増加する。\n・攻撃には１０％の「黒血侵食」効果を付与する。\n・自身のあらゆる解除可能なデバフを解除する。\n・この攻撃には追加で１つの五行の力を含む「陰陽術」が付く。\n『用語』\n黒血侵食：目標に与えたダメージの一定割合の最大HPを減少させる、デバフ解除では解除できない。\n陰陽術：呪文効果は以下の通り。\n・木の呪文：ランダムで１体の敵を「悪夢」にする。\n・火の呪文：ランダムで１体の敵のダメージ倍率を８０％上げる\n・土の呪文：ランダムで１体の敵の攻撃と防御を２０％吸収する。\n・金の呪文：５０％の確率でランダムで１体の敵を「麻痺」にする。\n・水の呪文：ランダムで１体の敵から２００点の戦意を吸収する。\n悪夢：１ターンの間、攻撃を３５％、防御を７０％低下させ、解除不可、同時に「悪夢」になるのは１体まで。\nポイント：\n全体攻撃を行いつつ、自陣が有利になる様々効果をもたらす陰陽術の効果が強いです。\n全体を黒血侵食に出来る点もなかなか強いです。\nさらに、自身のデバフを全て解除できる点も便利です。"
      },
      "evolution": {
        "fire": [
          "Lv1: 意志の継承\n効果：\n・各味方キャラが初めて倒されるとき、その意思を継承する。（増傷＋５％、減傷＋５％、累積可能で、HPを１０％回復し、倒されたキャラの残り戦意の１００％を継承する）\nポイント：\n元々あったパッシブの意志の継承が強化される形で対象が広がり受け継ぐ戦意の量も増えるので強いです。",
          "Lv2: 外道退治\n効果：\n・スキルの攻撃対象を残りHP割合の最も低い敵へと変更し、目標にかかっているバフ効果を全て解除する。\n・スキルの初期発動確率が３０％から５０％にアップする。\n・初めて奥義を発動すると、このターンは必ずスキルを発動可能。\nポイント：\n攻撃目標が残りHP割合の最も低い敵になることで敵を倒しやすくなるのが便利です。\n目標のバフ効果を全て解除する点が強いです。\nスキルの発動確率が上がる点も有難いです。",
          "Lv3: 冥道陰陽\n効果：\n・奥義の「黒血侵食」効果は２０％へとアップする。\n・奥義に付いていた五行の力を含む「陰陽術」が２つ付くようになる。\nポイント：\nただでさえ強かった五行の力を含む陰陽術が２つ付くようになることがとにかく強力です。\n黒血侵食の威力アップも強いです。"
        ],
        "ice": []
      }
    },
