    "skills": {
      "normal": {
        "name": "ソロモンの超攻撃",
        "text": "効果：\n・横１列の敵を攻撃し、２２５％のダメージを与える。\n・２００点の戦意を吸収し、「悪夢のエネルギー」を１つ獲得する。\n・２５％の確率で目標に「甘い夢」をかける。\n『用語』\n悪夢のエネルギー：１つの「悪夢のエネルギー」ごとにソロモンの３％コントロール率を高める（最大９つ獲得可能、２ターン持続。エネルギーが満杯状態に直接最大値で発動する）。\n甘い夢：１ターン寝かせ、その後目標を「夢語り」状態に入らせる。\n夢語り：次回攻撃の最終ダメージを５０％減らし、デバフ免疫を無視し、解除不可。\nポイント：\n確率ですが、１ターン寝かせた後に、目標の与ダメージを半減にするデバフをかけれるのがとにかく強力です。\n自身のコントロール率を上げれる点もかみ合っています。\n目標の戦意を吸収出来る点も強いです。"
      },
      "passive": {
        "name": "ジェディディアー覚",
        "text": "効果：\n・自身の減傷、スキル確率＋３０％。\n・味方の攻撃が「甘い夢」状態の敵に命中するたび、または敵を「甘い夢」状態にするたびに、ソロモンは「悪夢のエネルギー」を１つ獲得する、この効果は１ターンに最大３回発動可能。\n・「悪夢のエネルギー」が上限に達すると、味方全体にソロモンの攻撃力１５０％のHPを回復する。\n・攻撃された場合、自分のHPが６０％以下になると、ソロモンはスキルで反撃し、ターンごとに最大１回、優先的に奥義反撃する。\n・自身は「夢語り」効果を免疫する。\n・自身が「甘い夢」状態になった場合、自身のデバフ状態と今回の「甘い夢」状態を追い払い、「悪夢のエネルギー」を１つ獲得する。\n・「悪夢のエネルギー」を獲得するたびに１００点の戦意を回復する。\n・致命的なダメージを受けた時は陣亡せず、自身のターンになる時に２５％のHPと５００点の戦意を回復し、２つの「悪夢のエネルギー」と戦意削減効果１ターンを獲得し、奥義減傷とスキル減傷を永久的に１５％アップする。（重ね合わせ可能、復活後継承可能）この効果は戦闘毎に最大１回発動する。\nポイント：\n致命的なダメージを受けた場合、１回復活し、耐久面が永続的に強化されるのが強力です。\nHPが一定値以下になるとスキルまたは奥義で反撃できるのが強いです。\nパッシブで自身の減傷とスキル確率を大幅に上げれるのが強いです。\n条件はありますが、味方全体を回復できるのが強いです。"
      },
      "ultimate": {
        "name": "七十二柱の魔人ー降臨ー絶望",
        "text": "効果：\n・横１列の敵を攻撃し、３５０％のダメージを与え、自分の攻撃力と防御力とコントロール率を＋２０％、１ターン持続する。\n・３５％の確率で後列の敵に「甘い夢」をかける。\n・もし、攻撃前に自身が９つの「悪夢のエネルギー」を持っていれば、全ての「悪夢のエネルギー」を消耗し、エネルギー満杯状態に入る（「悪夢のエネルギー」最大層数のバフ効果と同じく、同じ種類の他のバフと重ね合わせ可能、１ターン持続する）\n・もし自身の会心率が目標の会心抵抗率より高い場合、自身は超過した数値の４０％の会心強度を得る。\n・次回味方のターンが始まると、４０％の確率で自身（ソロモン）に「甘い夢」をかける。\nポイント：\n複数体の敵に攻撃を与えながら、強力なデバフ効果である甘い夢をかけれる可能性がある点がとにかく強力です。\n奥義後にコントロール率が上がるのも、強力だけど確率があまり高くない甘い夢とかみ合っています。\n自身にデバフである甘い夢がかかる可能性がありますが、パッシブのおかげでメリットになります。"
      },
      "evolution": {
        "fire": [
          "Lv1: 悪夢\n効果：\n・攻撃を受けた時、「悪夢のエネルギー」が９つの場合、奥義で反撃し（戦意を消耗せず、１ターンに１回のみ）、その反撃は敵の戦意を回復させない。\n・味方のターンの前に、ランダムに戦意が（多分）１０００点未満の味方１人のキャラに１５０点の戦意を回復する。\nポイント：\n条件はありますが、戦意の消耗なしで奥義で反撃できるのが強力です。\nまた、一定値以下の戦意をもった味方１人の戦意を回復できる点も便利です。",
          "Lv2: 悪夢強化\n効果：パッシブ（ジェディディアー覚）に以下の効果を追加する。\n・致命的なダメージを受けた時は陣亡せず、自身のターンになる時に２５％のHPと５００点の戦意を回復し、２つの「悪夢のエネルギー」と戦意削減効果１ターンを獲得し、奥義減傷とスキル減傷を永久的に１５％アップする。（重ね合わせ可能、復活後継承可能）この効果は戦闘毎に最大１回発動する。\nポイント：\n分かりづらいですが、パッシブの復活効果とまったく同じものがもう一つついて、戦闘中に２回復活し、耐久面が永続的に大幅に強化されるのがとにかく強力です。",
          "Lv3: 夢語り\n効果：\n・味方のターンの前に、ランダムに１人の味方キャラの「夢語り」状態を解除。\n・味方全員が「夢語り」状態に入っていない場合、ソロモン自身は「悪夢のエネルギー」を１つ獲得する。\n奥義（七十二柱の魔人ー降臨ー絶望）を強化する。\n・後列の敵に「甘い夢」をかける確率が５０％になる。\n・次回味方のターンが始まった時に１００％の確率で自身（ソロモン）に「甘い夢」をかけるようになる。\nポイント：\n奥義で強力なデバフを後列の敵にかけれる確率が上がるのが強力です。\n悪夢のエネルギーを集めやすくなるのが強いです。\n自身への甘い夢デバフはパッシブによってメリットになります。"
        ],
        "ice": []
      }
    },
