    "skills": {
      "normal": {
        "name": "鯨突ー踏波ー覚",
        "text": "効果：\n・敵1体に３００％のダメージを与え、さらに３０％の確率で主目標に「眩暈」をかけ、「クジラ伸び代」を２.５％保存する。\n・「黒血侵食」された目標に５０％の追加ダメージを与え、戦意を１５０点回復する。\n・戦場にいる敵の３分の１以上が「黒血侵食」に影響された場合、「鯨の攻」が発動する。\n『用語』\n鯨の攻：\n・主目標以外の敵にも１００％の範囲ダメージを与え、２０％のスキルダメージも与える。\n・「黒血侵食」された目標をそれぞれ３０％の確率で「沈黙」させる。\n黒血侵食：目標に与えたダメージの一定割合の最大HPを減少させる、デバフ解除では解除できない。\n眩暈：敵の行動を１ターン封じる。\n沈黙：奥義を１ターン封印する\nポイント：\nダメージを与えつつ、確率ですが敵を行動不能に出来る点が強いです。\nまた相手に黒血侵食がいれば全体攻撃になったり、威力が上がったり、沈黙を与えられる点も優秀です。"
      },
      "passive": {
        "name": "巨鯨の力－覚",
        "text": "効果：\n・自身のスキルダメージ＋20％、奥義ダメージ＋20％、戦意回復速度＋２０％。\n・登場したターンでは、デバフを免疫する。\n・攻撃を受けHPが５０％以下の場合、「鯨の襲」で反撃する。\n・自身の全ての与ダメージ量から５％が「クジラ伸び代」に保存され（最大HPの５０％まで）、敵の攻撃後（通常攻撃、奥義、スキル、追撃）自身の残りHPが５０％を下回るたびに、「クジラ伸び代」を消耗し、その数値分HPを回復して最大５０％まで回復可能（この回復は治療量の増減効果の影響を受けず、コントロールされた場合は発動しない）。\n・登場時に１０％の「クジラ伸び代」を獲得し、自身の「クジラ伸び代」が尽きた時に、直ちに「鯨の佑」を発動する。\n『用語』\n鯨の襲：戦闘毎の初発動は戦意の消耗なしに奥義で反撃し、その後はスキルで反撃、反撃は敵に戦意を回復させない、１ターンに１回のみ。\n鯨の佑：自身の奥義抵抗＋２０％、スキル抵抗＋２０％し、自身の生命値を５０％まで回復（この回復は治療量の増減効果の影響を受けない）、さらに戦意を３００点と「クジラ伸び代」を３０％回復する。１戦闘につき１回のみ発動可能。\nポイント：\nどれだけダメージを与えたかが重要になってきますが、HP５０％以下になっても、複数回回復できる点がとにかく強力です。\nダメージの威力が重要なので、攻撃面が上がるステータスアップ効果もかみ合っています。\nまた、戦闘中１回とはいえ奥義で反撃できるのも強いです。"
      },
      "ultimate": {
        "name": "鯨戯ー超大潮流ー巨嵐",
        "text": "効果：\n・目標のブロックと減傷を無視して、敵全体を攻撃、２００％のダメージを与える。\n・２ターンの間、自身の攻撃力、防御力、会心率を２０％上げる。\n・３５％の確率で各目標を「眩暈」にさせる。\n・５０％の確率で各目標を「重症」にさせる。\n・「クジラ伸び代」を５％保存する。\n『用語』\n重症：１ターンの間、目標の戦意回復速度を１０％低下させ、さらに「禁療」にする。\n禁療：２ターンの間、目標のスキルより受ける治療と回復効果を１００％ダウン。\nポイント：\n複数の敵に眩暈や重症をかけれる可能性がある点がとにかく強力です。\n敵のブロックと減傷を無視できる点も強いです。\nまた、クジラ伸び代のために与ダメージが重要なので、攻撃的なステータスアップ効果もかみ合っています。"
      },
      "evolution": {
        "fire": [
          "Lv1: 鯨の蝕\n効果：奥義（鯨戯ー超大潮流ー巨嵐）に以下の効果を追加する。\n・「鯨の蝕」を追加発動。\n・「黒血侵食」状態の敵が１人増加するごとに自身のスキルダメージと奥義ダメージが１０％アップする（１ターン、最大３０％まで）\n・「重症」が「超重症」に昇格する。\n『用語』\n鯨の蝕：ランダムに敵１～６体に自身の攻撃力５０％の戦意回復できない追加ダメージを与える。そして、そのダメージの１００％の「黒血侵食」をかける。\n超重症：目標の戦意回復速度を２０％下げ、２ターンの間、治療禁止と吸血禁止を付ける。\nポイント：\nランダムですが奥義に追撃効果がのる点が強いです。\nまた、黒血侵食の敵がいればさらに攻撃力を上げれる点もクジラ伸び代とかみ合っています。\nさらに、デバフの強化もありがたいです。",
          "Lv2: 鯨の力\n効果：パッシブ（巨鯨の力－覚）に以下の効果を追加する。\n・智将から受けるダメージが３０％減り、力将への与ダメージが３０％アップする。\n・「黒血侵食」された各敵目標は長宗我部元親に「鯨の力」を１つ提供。\n・「黒血侵食」された敵が陣亡するたび、自身は今回の戦闘終了まで「鯨の力ー久」を１つ獲得する。\n鯨の力：１つ毎に攻撃力＋５％、破撃率＋５％でリアルタイムで更新し、最大５つまで、解除可能。\n鯨の力ー久：１つ毎に攻撃力＋５％、破撃率＋５％、重ね合わせの上限なし、解除不能。\nポイント：\n黒血侵食された敵に応じて、攻撃性能がさらにパワーアップする点が強力です。\nまた、苦手な智将への耐久面が上がる点も強いです。",
          "Lv3: 超重症\n効果：スキル（鯨突ー踏波ー覚）に以下の効果を追加する。\n・ダメージに２０％の「黒血侵食」の効果を付け、「鯨の力」が発動した場合、まだ「超重症」に追加されておらず、かつ前の１ターンでHP回復がもっとも多い敵２人に「超重症」を追加する。\n奥義を撃った際に、２ターンの間、「超重症」をかける確率が５０％アップする。\nポイント：\n奥義を撃った後に、超重症の確率をかなり高めれる点がとにかく強力です。\nスキルに黒血侵食の効果が付く点も敵の黒血侵食の数が重要な点とかみ合っています。"
        ],
        "ice": []
      }
    },
