    "skills": {
      "normal": {
        "name": "カラフルー流星乱舞～束",
        "text": "効果：\n・敵１体に３００％のダメージを与え、前回の奥義で命中した全ての目標の敵に３０％の範囲攻撃を与える（戦場内の敵に力将が１人いる毎に、1倍増加。最低３０％、最大１８０％）\n・命中した各目標を確率１５％（主目標は２倍）で「眩暈」にする。\n『用語』\n眩暈：敵の行動を１ターン封じる。\nポイント：\n確率ですが複数の敵を行動不能に出来る点が強いです。\nまた、敵単体にダメージを与えつつ、条件次第で周りの敵にもダメージを与えれる点が便利です。"
      },
      "passive": {
        "name": "伝奇武者・覚",
        "text": "効果：\n・自身の増傷、減傷、会心強度、奥義ダメージ、奥義減傷を＋５％。\n・自身のコントロール抵抗を２０％高め、味方キャラ全体のコントロールの総合１０％に等しいコントロール抵抗を得る（リアルタイムで更新）最大３０％まで。\n・攻撃するごとに自身の増傷を＋５％し、２ターン持続し、最大３層まで。\n・登場時、３つの「一人当千」を獲得する。（最大３つまで）\n・敵のターンに入るごとに、（登場時敵人数／２）の「一人当千」を得る。\n・攻撃を受けるごとに、３０％～１００％の確率で（攻撃を受けた後の、自分のHP割合が低いほど確率が高くなる。HPが３０％以下だと最大確率になる）、「一人当千」を１つ消耗し、自身が損失したHPの２０％を回復し、すぐにスキルで反撃する（もし、攻撃されたときに戦意が満タンの場合、全ての戦意を消耗し、奥義で反撃する）。\n後列隊長技：\n・巴御前が登場してから1ターンの間、味方の後列が受けたダメージは５０％減少し、そして敵の戦意抑制効果を免疫する（この効果は解除または吸い取られない）。\n・戦闘ごとに後列隊長技が複数存在する場合でも、１種類しか有効にならない。\n『用語』\n一人当千：\n・自身の増傷、減傷、治療量＋１０％。\n・そして敵全体の戦意回復速度を３０％低下（デバフ免疫を無視）。\n・味方が戦場にいる任意キャラを攻撃すると（反撃追撃以外）、他の味方キャラは全員戦意を２０点回復（巴御前はこの効果が3倍）。\n・巴御前が陣亡した時、「一人当千」の効果は消えず、元効果の３０％まで低下する。\nポイント："
      },
      "ultimate": {
        "name": "カラフルー花火流星堕ー幻彩",
        "text": "効果：\n・敵１体に５００％のダメージを与え、自身の攻撃と防御＋１０％、１ターン持続する。\n・目標を中心に追加で範囲攻撃を与える。命中した全ての敵に巴御前の攻撃力の３０％の追加ダメージを与える。\n・攻撃後、自身に「奇襲」効果を追加。\n・毎ターン初めて奥義を発動した後（追撃反撃以外）、味方１人のデバフ状態を解除（コントロールされた味方優先）。\n・もし、今回の奥義が反撃で使用された場合、次回味方のターン開始時＜１００＋２０×命中目標数＞の戦意を回復し、＜３０％＋５％×命中目標数＞の確率ですぐ「一人当千」を獲得する（最大１つの「一人当千」を獲得する）。\n『用語』\n奇襲：\n・１ターンの間、自身の与ダメージと会心強度を＋１０％。\nポイント：\n敵単体に高威力のダメージを与えつつ、周りに範囲攻撃を与えれるのが強いです。\n与ダメージを１０％上げれる奇襲のバフ効果が強いです。\n味方のデバフを解除できるのが便利です。"
      },
      "evolution": {
        "fire": [
          "Lv1: 仁王立ち\n効果：パッシブ（伝奇武者・覚）に以下の効果を追加する。\n・「一人当千」の所持数が３つまで達すると、３つの「一人当千」を消耗し、各戦闘で１回のみ復活可能。\n・復活する時、６０％のHPと戦意１０００点を回復。\n・自身が登場または毎回復活する時、１ターンの間、戦意回復速度と減傷＋２０％。\n・後列隊長技の効果が強化され、味方の後列が受けたダメージを７０％減少する。\nポイント：\n後列隊長技が強化され、１ターンだけですが後列のダメージを７０％カットできるのが強力です。\nまた、条件がありますが１回戦闘不能から復帰でき、HPが６０％回復し、戦意も満タンになるのも強力です。",
          "Lv2: 応戦持久\n効果：スキル（カラフルー流星乱舞～束）に以下の効果を追加する。\n・各命中目標に各命中目標の現在HPの５％のダメージを与える。そしてその１ターンの間に目標が発動した奥義は、巴御前が損失したHPの１０％と戦意を５０点回復。\n・自身の減傷＋３％、２ターン持続し、３回重ね合わせ可能。\n・「一人当千」の効果が強化され、巴御前が陣亡した時「一人当千」は消えず、元効果の５０％まで低下する。\nポイント：\nスキルを使用した際に、敵の現在HPの５％のダメージを追加で与えれるのが強いです。\nまた、巴御前が陣亡した時の敵の戦意回復速度減少効果が強化される点も有難いです。",
          "Lv3: 戦場指揮\n効果：奥義（カラフルー花火流星堕ー幻彩）に以下の効果を追加する。\n・１ターンの間、自身の吸血率＋１５％。\nパッシブ（伝奇武者・覚）に以下の効果を追加する。\n・奥義を発動した後、ランダムで味方１人に戦意消耗なしで奥義を１回発動（この奥義のダメージ倍率は０.５倍でコントロールされた場合にも影響されないが、今回の奥義の追加や連鎖効果は発動しない）\n・後列隊長技の効果が強化され、味方の後列が受けたダメージを１００％減少する。\nポイント：\n後列隊長技が強化され、１ターンだけですが後列のダメージを無効にできるのがとにかく強力です。\nまた、奥義を発動した後に、ランダムに味方１名の奥義を戦意の消耗なしで撃てるのも強力です。\n自身の吸血率を＋１５％するのも地味に強いです。"
        ],
        "ice": []
      }
    },
