    "system": "月",
    "initialRarity": "UR",
    "illustUrl": "https://stat.ameba.jp/user_images/20240518/09/hetarerimuru/ad/da/j/o1536069115440132221.jpg?caw=800",
    "illustSource": "へたれリムルブログ",
    "illustCredit": "へたれゲームプレイヤーリムル (ameblo)",
    "skills": {
      "normal": {
        "name": "霊魂・聖霊の導き",
        "text": "効果：\n・敵１体に３００％のダメージを与える。\n・スキルを発動するたびに、スキルダメージ＋１５％、効果は戦闘終了まで有効、３回重ね合わせ可能、解除不可。\n・最大HPの５％と４００点の戦意を回復する（治療強化、治療削減などの効果に影響されない）\nポイント：\n敵単体にダメージを与えつつ、自身の体力を少しと多くの戦意を回復できる点が強いです。\nスキルダメージが少しずつ底上げされる点も便利です。"
      },
      "passive": {
        "name": "ワルキューレー覚",
        "text": "効果：\n・最大HP＋３０％、防御＋３０％。\n・登場時に、「ワルキューレの印」を１８つ獲得する。\n・攻撃された場合、「ワルキューレの印」を１つ消耗して、損失したHPの１０％と１２０点戦意を回復する（効果はターン毎にに２回のみ発動可能、治療強化、治療削減などの効果に影響されない）。\n・致命ダメージを受けるときに「ワルキューレの印」を持っている場合、「ワルキューレの印」を全部消耗して、自身の全てのデバフを解除し、最大HPの５０％まで回復し、コントロール抵抗＋１００％（１ターン持続）、減傷＋５０％（２ターン持続）。\n前列隊長技：\n・ブリュンヒルドが登場した時、１ターンの間、戦場を「神々のアリーナ」に切り替える。\n・戦闘ごとに前列隊長技が２種類以上存在する場合でも、１種しか有効にならない。\n『用語』\nワルキューレの印：「ワルキューレの印」を１つ持つ毎に、自身のパリー強度＋３％、会心抵抗率＋３％、解除不可、戦闘終了まで有効。\n神々のアリーナ：\n・味方キャラが行動する時、そのキャラ自身の３００点の戦意を回復し、全てのデバフ状態を解除する。\n・敵キャラが行動する時、全味方キャラの最大HPの１０％を回復する（治療強化、治療削減などの効果に影響されない）。\nポイント：\n防御面のステータスアップ効果により、智将ながらかなりの硬さをほこる点が強力です。\nまた、印が残っていれば１回致死攻撃を耐え、２ターンの間、かなり硬くなれる点も強力です。\n１ターンだけですが、味方のHP回復とデバフを全て解除できる点も強力です。\n戦闘開始から印がなくなるまで、少量のHPと戦意を回復できる点も強いです。"
      },
      "ultimate": {
        "name": "迎・聖霊の帰る場所・極楽天国",
        "text": "効果：\n・敵１体に５００％のダメージを与え、９５％の確率で「ワルキューレの聖痕」をかける。\n・４０％の確率で「眩暈」をかける。\n・「眩暈」が付与されている敵に、今回の奥義により与えたダメージの５０％相当の追加ダメージを与える。\n・今回の奥義により与えたダメージの２０％のHPを回復する。\n・今回の奥義を発動する時、自身が２つ以下あるいは１７つ以上の「ワルキューレの印」を持っている場合、奥義は「天国への引渡し」に入れ替わる。\n『用語』\n天国への引渡し：\n・敵全体を攻撃し、２５０％のダメージを与え、敵人数が少ないほどダメージが高くなる（最大５００％まで）。\n・ランダムで敵１体に「ワルキューレの聖痕」をかけ、それぞれの敵に４０％の確率で「眩暈」をかける。\nワルキューレの聖痕：１ターンの間、戦意回復速度をー１００％。解除不可。\n眩暈：目標を１ターン行動不能にする。\nポイント：\n条件はありますが、敵全体を高威力で攻撃し、敵複数を行動不能にできる可能性がある点がとても強力です。\n通常の奥義でも、目標をほぼ１００％の確率で戦意をたまらなくさせる点も強いです。\nまた、回復できる点も自身の硬さをさらに上げることになりかみ合っています。"
      },
      "evolution": {
        "fire": [
          "Lv1: 聖霊の力\n効果：\n・スキル発動確率＋３０％。\n・スキル使用時に本ターンで自分が発動した奥義により与えた総ダメージの５０％相当の「シールド」を獲得する。\n『用語』\nシールド：\n・２ターン持続し、解除不可。\n・シールドの量だけダメージをカットする。\n（例、シールド１０の状態で１００ダメージ受けたら、シールドはそのままで９０ダメージをHPにうける）\n・シールドの最小値は自身の最大HPの５％、最大値は自身の最大HPの１０％。\n・自身が後列にいる場合、シールドの量は元の３分の１にしかならない。\n・新しく得たシールドが現在のシールドの量を上回る場合、シールドがリセットされ、それ以外の場合はリセットされない。\nポイント：\n奥義発動後のスキル使用時にシールドが付くようになり、さらに硬くなるのが強力です。\nスキルが強いので、スキルの発動確率があがるのは有難いです。",
          "Lv2: 聖霊の憐れみ\n効果：パッシブ（ワルキューレー覚）に以下の効果を追加する。\n・登場時に「生命の光」と「ワルキューレの猛威」を発動する。\n・パリー率＋（１０％＋２.５％×戦場に残っている味方キャラ数）。\n・敵キャラから攻撃を受けるとき、２０％（前列にいる場合３５％となる）の確率でダメージを５０％カット。\n・「ワルキューレの印」が全部消耗された時、戦場を１ターンの間「神々のアリーナ」に切り替える。\n『用語』\n生命の光：味方全キャラの最大HP＋１０％、効果は戦闘終了まで有効。\nワルキューレの猛威：敵全キャラの攻撃力をー２０％、効果は戦闘終了まで有効。\nポイント：\nパッシブによる味方全キャラ最大HP増加と、敵全キャラ攻撃力ダウンがとにかく強力です。\nまた、パリー率の上昇や、３５％の確率でダメージカットなどでさらに硬くなる点もとても強力です。\n神々のアリーナの発動条件が追加されるのも便利です。",
          "Lv3: 聖霊の慈悲\n効果：奥義（迎・聖霊の帰る場所・極楽天国）に以下の効果を追加する。（入れ替わった奥義も含む）\n・奥義は目標の減傷率と奥義減傷率を１０％無視でき、そして攻撃力が一番高い目標１体に「神々の威勢」をかける。\n『用語』\n神々の威勢：ブリュンヒルドは目標の攻撃力、増傷を５％吸収する。効果は２ターン持続し、PVE無効、重ね合わせ不可、解除不可、吸い取ることもできない。\nポイント：\n奥義で目標の攻撃力などを一部吸収することで自軍を有利にし、敵軍を不利にできる点が強いです。\nまた、減傷率などを一部無視できる点も強いです。"
        ],
        "ice": []
      }
    },
