    "initialRarity": "SSR",
    "illustUrl": "https://stat.ameba.jp/user_images/20241018/18/hetarerimuru/c8/34/j/o1037046715499434510.jpg?caw=800",
    "illustSource": "へたれリムルブログ",
    "illustCredit": "へたれゲームプレイヤーリムル (ameblo)",
    "skills": {
      "normal": {
        "name": "真・爆焔轟雷墜",
        "text": "SSR時との違い：\n敵を攻撃する威力が１６０％から３００％に大幅アップしています。\n追加効果のダメージがパリーを無視できるからシールドを無視できるに変更になっています。\nポイント：\n追加で相手に呂布の最大HPの５％分のダメージをシールドを無視して与えれる点が強力です。\n味方１名の戦意を回復できる点も優秀です。"
      },
      "passive": {
        "name": "無双の鬼・覚",
        "text": "SSR時との違い：\n呂布が一回の攻撃で受けるダメージの上限が最大HPの６０％から５０％に減少。\n呂布のHPが回復する条件がHPが４５％以下になった時から５０％以下に緩和。\n「闘気」の効果が解除不可に強化。\n『用語』\n闘気：\n・防御＋５％、効果は戦闘終了まで有効、解除不可、最大６回重ね合わせ可能。\nポイント：\n攻撃を受けるたびに防御力が上がる点がとても強力です。\n自身のHPが５０％以下になった時にHPを回復できる点がとても強力です。\n簡単な条件でスキル発動率が上がっていく点がとても強力です。\n自身が１回で受けるダメージの上限に制限がある点が強力です。\nパッシブでステータスが上がる点が強力です。"
      },
      "ultimate": {
        "name": "無双・真煉獄爆焔衝・鬼神",
        "text": "SSR時との違い：\n敵を攻撃する威力が４００％から５００％に大幅アップしています。\n闘気を消耗する際にかかるバフの効果時間が１ターンから２ターンに強化。\nポイント：\n目標の最大HPの５％を吸収できる点がとても強力です。\n闘気を消耗して発動するバフがとても強力です。\nHPが初めて４０％以下になった時にデバフを全て解除しHPを回復できる点が強力です。"
      },
      "evolution": {
        "fire": [
          "Lv1: 鋼鉄の身\n効果：スキル（真・爆焔轟雷墜）に以下の効果を追加する。\n・自身の２００点の戦意と最大HPの２.５％を回復する。\n・４０％の確率で「眩暈」をかける。\n・スキルを発動後２ターンの間に攻撃されると、当該攻撃をブロックしていない場合、自身ブロック率＋２０％、無限に重ね合わせ可能、解除不可。\n・ブロック成功時に重ね合わせたブロック率はリセットされる。\n＊ブロック強度＋３０％はおそらくパッシブだと思います。＊\n『用語』\n眩暈：\n・敵の行動を１ターン封じる。\nポイント：\nブロックしていない場合、ブロック率が大幅に上がっていく点がとても強力です。\nスキル発動時に戦意とHPを少し回復できる点がとても強力です。\n敵を行動不能にする可能性がある点が強力です。\nブロック強度がパッシブで上がる点が強力です。",
          "Lv2: 戦神の力\n効果：パッシブ（無双の鬼・覚）に以下の効果を追加する。\n・呂布は１０％の生命極限を持ち、生命値は最大HPの１０％以下に減少しない（登場及び復活時、戦場にいる敵キャラ人数により、１名につき、生命極限＋５％）。\n・攻撃を受けると、呂布はダメージ量同等の「無双の戦神」を獲得する（一回で受けるダメージ上限を超える分の数値、生命極限を超える分の数値も含める）。\n・敵ターン開始時に、「無双の戦神」が呂布の最大HPの７５％を超えている場合、全ての「無双の戦神」を消耗し、この効果により消耗された「無双の戦神」の数値は呂布の最大HPの７５％につき、呂布に「神の殞落」を刻み付ける。\n・もし呂布が前列にいる場合、後列の味方キャラの被ダメージを３０％分担し、呂布は分担により受けるダメージを３０％下げ、呂布のHPが２０％以下の場合、分担行為を発動しない（分担ダメージから「無双の戦神」を獲得できない）。\n『用語』\n神の殞落：\n・１つにつき、呂布の生命極限ー１５％、生命極限が０以下に減少する場合、呂布は生命極限能力を失い、効果は戦闘終了まで有効、解除不可、無限に重ね合わせ可能。\n・新たな「神の殞落」を獲得するごとに、１つの「戦神の威厳」を獲得する。\n戦神の威厳：\n・１つにつき、全ての敵キャラの攻撃ー５％、増傷ー５％、効果は戦闘終了まで有効、解除不可、最大５回重ね合わせ可能。\n＊呂布の生命極限についての大体のイメージ＊\n敵が６体いた場合、生命極限は４０％から開始され、呂布の最大HPの７５％分のダメージを合計で受けた場合に生命極限がー１５％されるので、大体呂布の最大HPの２２５％分のダメージを合計で受けるまでは生命極限の力で戦場に残ります。\nこの際、HPが減った分ではなく、受けるはずだったダメージの総量なので注意です。\nポイント：\n神の殞落による解除しかない生命極限による耐久力の高さがとにかく強力です。\n後列の味方への被ダメージを分担し、そのダメージを３０％カットできる点がとても強力です。\n神の威厳による解除不可の敵全体へのデバフがとても強力です。",
          "Lv3: 鬼神の意\n効果：奥義（無双・真煉獄爆焔衝・鬼神）に以下の効果を追加する。\n・目標の周囲（上下左右）の敵に、４０％のダメージを与える。\n・攻撃＋１０％、防御＋（１０％＋５％×「神の殞落」スタック数）、効果は２ターン持続し、解除不可。\n・奥義を発動後、コントロール抵抗率＋２０％、２ターンの間に攻撃を受け、新たなコントロール効果をかけられると、呂布は１００点の戦意を回復し、かける側のコントロール抵抗率を１０％吸収し、効果は２ターン持続し、解除不可。\n・目標とその周囲に呂布の防御の２５％分の追加ダメージを与える。\nパッシブ（無双の鬼・覚）に以下の効果を追加する。\n・スキル発動率＋２０％、奥義減傷＋２０％。\n・（おそらく味方ターン開始から）味方ターン終了まで、全ての味方キャラが受けたダメージ（２５％ー５％×呂布以外の戦意満タンの味方キャラ数）減少する。\nポイント：\n味方ターンの間、相手からの被ダメを一部カットできる点がとても強力です。\n優秀なスキル攻撃をかなり高い確率で発動できる点がとても強力です。\n奥義後にコントロール抵抗率を上げつつ条件次第で相手のコントロール抵抗率を吸収しつつ戦意を少し回復できるのが強力です。\n奥義に追加ダメージが２つ付くのが強力です。"
        ],
        "ice": []
      }
    },
