    "cv": "あいりん",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA1MjVfOTgg/MDAxNjg0OTkzMjg0ODE4.rSBo0VNs0-sFZpWJCo5MOLJkdYZFPrD1KPahE8gQIuIg.0baPVtHomBZuU9k9Y7E3YWQXPkhqEU_Q1ITxpraw0nAg.JPEG/%EC%B9%B4%EC%9D%B4%EC%82%AC%EB%A5%B4.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "この混沌とした時代、争いの絶えない世界を、吾が終わらせる！そして吾の名は、全ての者に知れ渡ることだろう！吾の邪魔をする者は、例えお前であっても滅ぼすしかないが、よいか？",
      "ホーム画面タップ１": "吾の足元に跪き、もっと吾の名である｢カエサル大帝｣を呼ぶがよい！なぜそのような事を、だと？お前の口から何度も聞きたいからだ！さあ、もっと呼ぶのだ！",
      "ホーム画面タップ２": "気高き風体、冷酷な顔、無常な言葉、これらがなければ、帝王たる吾の威厳を確率できない。たとえそれが、吾の不本意なものであってもな。",
      "ホーム画面タップ３": "書物を読めば、見識も心も豊かになる！人間が興奮すると膨らんで大きくなるものとは何か知っているか？……瞳だ！何と勘違いしたのだ！",
      "ホーム画面下着状態": "いや……これはダメだ、吾は至高無上の帝王だ。何故こんな恥ずかしいことをする？うっ、はあ……すごく気持ちいい！気持ちいいぞ…！",
      "ホーム画面下着タップ1": "ああ……くすぐったい……もうダメだ…でも…気持ちいい！この感覚は一体なんなんだ…もっと、もっとしてくれ…！",
      "ホーム画面下着タップ2": "今のは夢か？ぜ……全部夢なのか？情けないな、どうやらあの本に影響されたみたいだ。お前……今日の事を……ばらさないでくれ……頼むから！",
      "ランクアップ": "よし、これで世界征服を続けられる！",
      "覚醒": "進歩はまだまだ遅いな！敵は弱いまま待ってくれないぞ！",
      "調教道具1": "------------------------------",
      "MVP宣言": "偉大なる帝王にとっては当然のことだ！",
      "プレゼント-挨拶": "吾に朝見したいと聞いたが、何の用だ？",
      "プレゼント-感謝1": "悪くない。",
      "プレゼント-感謝2": "絶品だな、ありがとう。",
      "プレゼント-感謝3": "嬉しいよ。",
      "クローズアップ": "------------------------------",
      "スキル1": "ひざまずけ！",
      "スキル2": "自業自得だ！",
      "スキル3": "吾を喜ばせろ！",
      "奥義1": "偉大なる帝王に臣服せよ！",
      "奥義2": "吾の意志は、帝国の意志だ！",
      "死亡": "う...これで私の統治は...終わり...なのか？"
    },
    "story": "【その一】\nカエサルは没落貴族の子として平民の中で育ったので、民衆の窮状をよく理解することができた。彼女はかつて蛮族の捕虜となり難を逃れたことも、贖罪のために海賊に投獄されたことも、間違った先生に師事して学ばず哀れまれたことも、貴族に迫害され流刑になったこともあった……が、これらの苦難はカエサルを落ち込ませることなく、むしろ彼女を強くした。その後、彼女は地方官時代に自ら借金をして民衆のために建設し、戦場では軍隊を率いて、すべての戦いで勝利に導いた。\n\n彼女は女として、男性が多い軍隊を率い、男女のエロいことは知らず、軍規を厳しくした。一方、彼女自身は男女ともに高い評価を得ていたので、彼女の周りには抜け目のない有能な忠臣が多く集まった。彼らは常にカエサルの考えを勝手に過大解釈していた。彼らを厳しく批判しても、まるで楽しんでいるかのように見えるのである。いつの間にかカエサルは、部下たちの擁護と民衆の支持を得て、ローマの権力の頂点に上り詰めていたのである。\n\n【その二】\nカエサルは民衆に愛されていたが、貴族で構成される元老院は彼女を非常に嫌っており、常に彼女の政策に反対していた。そして民衆と兵士たちの利益に関わる話題について、カエサルは一歩も譲らなかった。元老院でカエサルが元老院議員たちと議論したことも何度もあったが、ほとんど彼女の有利になるようなものであった。しかし、彼女が学んだ弁論法は雄弁で彼女の本意ではなかったので、その後に彼女はしばらく落ち込んで、隅にしゃがんで閉じこもることもあった（邪神はこの隙間を利用した）。\n\nカエサルは読書が好きで、いろいろな本を読んでいた。また、彼女はいつも元老院との論争に飽きると、軍隊を戦争に連れ出すことにしていた。そして戦争で見たことを本に書き、ローマの人々を大いに喜ばせた。その中で、少女漫画や大人向けの漫画など、ローマでは禁止されていた本を多く獲得し、エロいのが好まないカエサルは批判的な目で読んでいたが、読み進めるうちに、エロいことについて考えるようになった。\n\n【その三】\nう～ん……今日も元老院で大暴れしてしまった。あの議員が口から泡を吹くほど叱り飛ばしてしまったな。\n\nそいつらは、頑固で普通のコミュニケーションでは全く聞かないわけだから。でもまあ、やはり強く叱りすぎたようだ。\n\nしかし、貧しい民衆たちに土地を与えなければ、彼らは遅かれ早かれ反乱を起こすだろうし、退役軍人に手当を与えなければ、誰も兵士になりたがらないだろう？\n\nもう、そんなことより、何か気分転換になることでもしようか。そうだな……兵士の訓練をしている人もいるし、隣国からの使者を招待している人もいるし、向こうでは水道橋を掘る人も、小麦を収穫している人も沢山いるよな。\n\nよくも全部やってくれたよな。じゃあ、吾は何をすればいい？\n\n本を読むしかないよな。ちょうど、昨日の哲学の本がまだ少し残っているんだ。\n\n待て、誰もいないのなら、「あれ」を読んでみようか？少し読むくらいなら大丈夫だろう！\n\nうわー、この本のお姉さん、こんなに薄着なのに可愛く見えるのなぜ？こんな服を吾も試着してみようかな……いやいや、そんなの着ちゃダメだろう……こっそり着てみるかな？\n\nそういえば先日、街でこれを着ている人がいた気が……あっ！まさかあのお姉さん、本に書かれているようなことをしたばかりだったのか？\n\n白昼堂々、あれやこれやと……そして、相手の奥さんが突然帰ってきて、こんな格好で……体にあれやこれやを付けられているままで街に出てきているなんて！\n\nフーハー、フーハー、フーハー……",
