    "story": "【その一】\n関雲長は幼い頃から『春秋』『礼記』などの古書を熟読し、忠義の心を抱いていた。不幸にも、彼女が住む小さな町の役人は悪人で、毎日民から物を横領するため皆苦しんでいた。ある日、関雲長は悪人に忠義の心を持ち続けるという拷問に耐えきれず、ついに役人を斬ってしまった。しかし、そのために故郷からは追放されることとなった。故郷から離れる道中、彼女は山賊を追い払って村人を助けた。すると彼女に従ってくれる村人たちが集まり、忠義を重んじる彼女の評判は主要都市の間に広まることとなった。多くの城主が彼女に財宝を与えて口説こうとしたが、それらは彼女の心を動かさなかった。彼女は生涯ただ一人の明君を追い求めるべきだと思っている。それらの城主たちは明らかに明君とは言えない。村人たちを率いて盗賊と戦っているうちに、彼女の軍事の才が徐々に開花し始め、彼女の武芸の才と共に天下に名を馳せるようになった。そして、「武聖」の名を勝ち取ったのだ。\n\n【その二】\n邪神が侵攻してきた時、関雲長はちょうど奥地で山賊と闘っていて、一瞬にして敵に包囲されてしまった。皆がパニックに陥る中、関雲長は立ち上がって民衆を落ち着かせた。彼女は軍事の才を発揮して皆を率い、長時間抵抗して敵を食い止めた。当時はちょうど雨季だった。邪神軍の妖魔たちが山下の谷に陣取っているのを見て、また大雨によって荒れ狂っている川を見て、関雲長はある計画を立てた。すぐに村人たちを率いて木を切って小舟を作り、まだ使える雨具を集め、あちこちの洪水が起きている口を全て塞いだ。その夜、天気に恵まれ風も雨も激しくなった。邪神軍が驚き、テントから出てみると、関雲長の軍勢がすさまじい声をあげて走ってくるのが見えた。慌てた邪神軍たちが逃げようとしたが、関雲長の軍勢によって小路に追い込まれた。関雲長は馬に乗って先陣を切り、手にした青龍偃月刀は誰にも止められないまま、皆を率いて邪神軍を皆殺しにした。その後、はじめに用意おいた小舟に乗って水勢に乗り、邪神軍の包囲を突破して皆を故郷に連れて帰った。\n\n【その三】\n公室のために何でも行うのは、忠である。\n\nゴホン、おばあさん、こんにちは。い、いえいえ！『春秋』を暗唱しているだけです。\n\nお手伝いしましょうか？前回借りた本ですね。大丈夫です。本は読めば読むほど意味の深さを理解できますよ。\n\n万巻の書を読み、万里の道を行くことです。\n\nえ？城内の塾の先生たち？\n\nあの人たちは学問をひけらかすことしか知らない人間です。私と一緒にいる資格すらありません。\n\nあの人たちの話はやめてください。おばあさんはこれからどこへ行くんですか。\n\n豆？それ好きなんです、ありがとうございます。\n\n私はまだありますから、おばあさんが好きならそれで十分です！",
    "skills": null,
