    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA1MjRfMjM0/MDAxNjg0OTA5NTM4MDE0.u0gDLVCjRB8cYDAlughJ17DUQ-VMbyUFqtbGjOdlO0Qg.-fOdPnsAJeFz-Gx5JHBCcwXMqNGToud-PFUr-yAF4x0g.JPEG/%EC%A3%BC%EC%9C%A0.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
