    "role": "風雨召喚、石兵八陣",
    "cv": "ししゃも",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA1MjRfOTEg/MDAxNjg0OTA4OTc4OTU0.uS8eYSeRUGjvIZTcbHhtnc0NGVYVsChxDOqrOG6qAJ0g.DdSQTR3JPwENwGnKt4ezRuKq4YXRFPmVbgYptLM7gTEg.PNG/%EC%A0%9C%EA%B0%88%EA%B3%B5%EB%AA%85.png?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "私は諸葛孔明…一応軍師やってます……あぁ……自己紹介疲れた……もう帰る……",
      "メインページでタップ1": "めんどくさい……もう何もしたくない……",
      "メインページでタップ２": "あぁ……何もしてないけど疲れた……誰か心優しい人が私の為におやつ取ってきてくれないかな～？",
      "メインページでタップ３": "ずっとダラけてたいなぁ……天下なんてやりたい人にやらせればいいじゃん……",
      "メインページでタップA1": "仕事ばっかりしなくても……たまには私のところでのんびりすればいいのに。あ、その時はおやつ、忘れないでね。",
      "メインページでタップ-下着1": "この孔明を追い詰めるとは……こいつ、ただ物じゃないな……",
      "メインページでタップ-下着2": "うぅ……く、屈辱だ……ただで済むと思うなよ！",
      "星アップ": "あれ？もしかしてまた強くなった？何もしてないんだけど……",
      "覚醒": "お願いだから…もう…やめて…",
      "親密アイテム1": "この屈辱……一生忘れないから！",
      "親密アイテム2": "もういい加減にしてよ……私だって怒るんだからね！",
      "MVP宣言": "あ～あ、疲れた……誰かおんぶしてよ……",
      "スキル1": "勝手に消えてくれよ……",
      "スキル2": "疲れた……もう動きたくない……",
      "奥義1": "石兵八陣はこう……だっけ？まぁ……どっちでもいいや",
      "奥義2": "抜け出せるものなら、抜け出してみなよ！",
      "死亡SE": "うぁ～……"
    },
    "story": "【その一】\n孔明は幼い頃から独特の知性を発揮していた。様々なことをすぐに覚え、その後は寝たり空を眺めたりして過ごすことが多く、たまに何かを要求されても、大人が代わりにやってくれるように巧みに「手配」していた。\n\nついにある日、孔明の両親は、彼女の知性が怠惰さに活かされていることに気付き、賢いダメ人間に育つことを恐れて、彼女をある学者の家に弟子入りさせたのです。\n\n学者は長年、誰の弟子も受け入れておらず、孔明も誰かに師事するつもりはなかったので、学者が孔明に「もし、世の中に抗えない、恐ろしい、危険な存在がいたらどうするか」と尋ねたところ、「私は不可能を追求しない」と孔明は淡々と答えた。 孔明の答えがその学者に気に入られたのか、それから弟子になった。\n\n孔明は学者の山の書房で、多くの風変わりな人を見た。「北落師門」や「生きた炎」など奇妙な言葉を唱える学者、一ページを読むと嫌悪感と恐怖感を覚える本、邪悪で狂信的な目をしている書房の客たち...その中でも、孔明が奇妙な宝物を盗もうとして7回も捕らえた孟氏の話は、普通の話として語られるかもしれない。\n\nそれはもちろん、別の話である。\n\n【その二】\n匿名希望の孟氏は、孔明に捕まったことを認めず、「運が悪かっただけ」と力説していた。 いずれにしても、悪運の強い奴だと評価し、孟氏と孔明が知り合いになってしまったのだ。孟氏は「知恵」で勝てないので、和解を図っていた、不吉なものを盗みに来た理由も全部話した。彼女の家族が代々不吉なバケモノを召喚する宝物を守ってきた、それが誤ってなくしてしまった。少し前に、高僧から不吉な物がここに隠されているとの指示を受け、それを取り返しに来たのだと言う。この言葉に孔明は感動した。そこで、孔明の協力で警備員を騙し、図書館を守っている簿記係を逃れ、暗器から逃れ、多くの困難を乗り越えた。ついに宝物が隠されている地下宝庫を見つけ出し、不吉なものを手に入れた---火でも破壊できない秘密の書物---\n\n帰り際、孟氏は孔明に、なぜいつも不運にも彼女に出くわすのかと尋ねた。別れを惜しんだのか、怠け者の孔明はしぶしぶ次のように語った。「あなたの服装を見て、身分の高い人であることは明らかであり、そのような人が自分で盗みに来たのは、きっと人に言えない理由があるに違いない。そして、二人しか解けない罠を仕掛けたり、道しるべをすり替えたり、出入りの途中で待ち伏せしたり、防犯することはたやすい...」\n\n「私を馬鹿にしないで、黙ってくれる？」と孟氏は孔明の話しを遮った。\n\n【その三】\n人間は本能的に知識を探求し、答えを探し、困難を解決しようとする。\n\nそうすることで人間は成長し、心を豊かにし、利便性をもたらす。\n\nしかし、知識は無限を意味し、それは暗闇の中の未知のもの、深淵に隠された謎を意味する。\n\n探求すればするほど、暗闇の恐怖に深く沈み、迷子になって、混沌の中で気が狂ってしまう...\n\n私はそう思っている...\n\n要するに、私は書房で、奇妙な世界を十分に見てきた。そしてその奇妙さが、私をもっと知りたいという気持ちにさせてくれた。\n\nまったく...それは私を過大評価しているようです...たとえ夢の中で囁かれても、私はやる気になりません。\n\nでも、やっぱり...このまま放っておけない、これ以上無関係者を巻き込みたくない...\n\nでも楽しかった...孟氏の邪魔をして...封印されたはずの宝物を取り戻すのを手伝ったり、邪悪な宝庫を燃焼払ったり...まあ...きれいに焼けましたね...ああ、思い出すだけで疲れる...\n\nグー「お腹空いた...」\n\n...人は...なぜ食べないと生きていけないのか...食べる時...なぜ噛まないといけないのか...\n\nうう...考えるだけで怠い...\n\nもし...それを抗おうとする人がいたら...その人が私のところに来てくれたら...少しくらい手伝ってあげてもいいかもしれない...",
