    "role": "金剛不動、堅城鉄壁",
    "cv": "神代そら",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA1MjVfMjIg/MDAxNjg0OTkzMzYxODQx.qdWAnx5Od5bukMppKlkUOAuNA26Ke06gHOVTQGVYOmQg.lILFiOPH_ppfQ9rAt-p-mc3V9l8Qo3fTRaXhidMCuakg.JPEG/%ED%82%A4%EC%9A%94%EB%AA%A8%EB%A6%AC.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "おい！吾は平清盛、平家の棟梁であり、天下を取る者だ。吾を止めようとする者はすべて殺すのみ！だからお前もこれからどうするかわかったろう！",
      "ホーム画面タップ１": "汚れた手で触るな！それとも切り取って豚に食わせて欲しいのか！？ならば今から足で食べることを練習しろ！",
      "ホーム画面タップ２": "お前アホウか？両耳が聞こえないのか？違う？だったらなんでそんなバカなことするんだ！",
      "ホーム画面タップ３": "ふむ、お前の度胸はこの程度の物か？私と親密になりたいのに、それを口にする勇気がない？役立たずめ！いざという時、吾を満足させられないだろう！",
      "ホーム画面下着状態": "長くて硬い、まさか吾のおっぱいを見ただけでこんな様に……何だ！ビール瓶じゃないか！",
      "ホーム画面下着タップ1": "この軟らかいのはロープなのか、それとも革のムチなのか？どうして吾は乱暴なのが好きだと知っているんだ！そうじゃない？ただのベルトだって？",
      "ホーム画面下着タップ2": "これは…部屋の鍵？ってことは今夜部屋に来てそういうことをしないかという誘いなのか？……あぁ？考えすぎだと？何だ、ただ一緒にゲームをしたいだけなのか…",
      "ランクアップ": "平家の未来のために！",
      "覚醒": "少しずつ、この天下を吾の物にする！",
      "調教道具1": "------------------------------",
      "MVP宣言": "吾は1割の力しか出していないぞ、雑魚どもめ！",
      "プレゼント-挨拶": "いい知らせをくれなきゃ、どうなるかわかってるだろうな？",
      "プレゼント-感謝1": "ふむ、意外と美味いな",
      "プレゼント-感謝2": "アクメにしてくれる食べ物だ！",
      "プレゼント-感謝3": "くっ！これは我慢できない……！",
      "クローズアップ": "------------------------------",
      "スキル1": "ハア！",
      "スキル2": "身の程知らずが！",
      "スキル3": "いくぞ、続けぇっ！",
      "奥義1": "絶対無敵のパワー！",
      "奥義2": "邪魔者は全員死んでもらう！",
      "死亡": "吾がいなければ、平家は誰が守ってくれるのだろう？"
    },
    "story": "【その一】\n彼女は平家一門の支配者になりたいだけではなく、世界を支配するという野心を抱いていた 。\n\n自分の勢力を拡大し、世の中を支配できるようにするためなら、どんなことでもする。そこで彼女は軍隊を増強し、「主君に忠実」な軍隊を育成し、平家の政権維持のために重要な役割を果たすようにした。\n\nまた、平家の女性を有力な家来（貴族）に嫁がせ、政略結婚で巧みに自分の勢力を拡大し、腹心の家来の傍に置き、他勢力の機密を監視しながら、平家の権勢を固めることにした。\n\n彼女は軍事力の拡大だけでなく、経済も発展させ、音戸の瀬戸を開発し、摂津の福原に港を造って外国貿易を発展させることで、平家の収入を大幅に増やし、わずか数年で沢山の財産と世界を制覇する力を手にしたのである。\n\nこれは、平清盛の非凡な才能と強い個性があったからこそ実現できたことであり、彼女なくして今日の平家はあり得なかったとも言える。\n\n【その二】\nそんな強い女には、源氏の一族である源義経という宿命的なライバルがいる。\n\nこの流浪の剣士は、彼女が世界を支配するのに最大の障害だった。彼女はこの邪魔者を排除するために手段を選ばない。\n\n二人の出会いは、あの日だった。\n\nあの時平清盛は平家の敵である武士団体を討伐していて、残された侍たちは、平清盛によって崖に追い詰められ、崖から飛び降りて侍の尊厳を守るか、平清盛に殺されて屈辱的な死を遂げるかの二択しかなかった。\n\n絶望に追い詰められた侍たちがこのまま死のうと思ったとき、山で休んでいた源義経が、武士たちが危険な目に遭っているのを見て、助けに来た。\n\n平家と源家はすでに深い恨みを抱いており、源家に邪魔された平清盛は激怒し、何も言わずに源義経に喧嘩を売ったのだ。\n\nあまりの激戦に、兵士や侍たちは唖然とし、助けようと思っても、手を出したら命を落とすかもしれないと躊躇するほどだった。二人の戦いは、源義経が平清盛の腕を貫いたのを機に終わった。\n\nそして負傷した平清盛は部下の兵士を連れ帰るしかなくなった。平清盛はそれ以来、源義経を宿敵とみなし、彼女と再び決闘するために多くの部下に源義経の居場所を明らかにさせようとした。今度は恐らく命をかける決闘になるのだろう。\n\n【その三】\n「わが一族の未来のために、すべての障害を踏みつけ、すべての敵勢力を粉砕しなければならい！」\n\n「しかし、そのためには強靭さ、毅然さ、冷酷さが必要だ。」\n\n「この戦だらけの時代では、優柔不断、慈悲深い者は、他人の剣に切られる者にしかならない。」\n\n「私はそんな人になってはいけないのだ。私がいなければ、平家のアホ連中だけでは何もできない。」\n\n「燕雀安んぞ鴻鵠の志を知らんや！」\n\n「そんなことはあの浅い愚か者どもには理解できない。彼らは目先の利益だけで満足するだろうが、私はこの世界をすべて平氏のものにするのだ！」\n\n「いずれこの世界は平家のものになる！絶対にだ！」",
    "skills": null,
