    "story": "【その一】\n半兵衛は、竹中家の跡取りとして幼い頃から天才的な頭脳を発揮し、大人顔負けの頭の回転の速さと思考の深さを持ち、更に容姿端麗でもあり家臣たちにも期待されていた。しかし、神は公平であることを証明するかのように、半兵衛はその聡明さとは対照的に、非常に病弱であった。はじめは家族も些細な病気だと思い、病気療養中でも知識を身につけるためによく本を送ったので、半兵衛もベッドで読書する趣味をもった。しかし、半兵衛の病気は何度も再発し、更に色々な病気も次々と彼女を襲い、一年の大半を寝たきりで過ごすことになり、竹中家が名声を得ることができるはずだった戦争を何度も逃した。加えて、彼女は長年部屋に引きこもってあまり人に会わず、非常に人見知りになってしまい、他の勢力との付き合いが全くなくなってしまった。特に、彼女の美貌に引き寄せられて来た求愛者を避け続けていた。 その結果、竹中家は他勢力から疎まれ、家臣たちも次々と去り、半兵衛はひとりぼっちになってしまった。\n\n【その二】\nある日突然、豊臣秀吉という見知らぬ人間が半兵衛を見つけた。 秀吉は、ここに助けを必要としている人がいる聞いて来たのだが、半兵衛は知らない人に話しかけるのが怖く、姿を見せずにドアの後ろに隠れた。 数日後、秀吉はおいしい食べ物をたくさん持ってまたやってきた。半兵衛が出てこなくてもドアの前にずっと立って待っていた。 半兵衛は、自分は肉を食べられないのだと言って秀吉を追い返した。 三度目は、秀吉は薬草をたくさん持ってやってきた。半兵衛がなんの病気なのか知らなかったので、あらゆる薬を持ってきたのだ。そして、ドアの前で「しっかりして、少しでいいから開けて」などと説得した。 半兵衛は泣いたり笑ったりしていたが、実は人見知りのせいで、ただ静かに読書したいだけだったのだ。仕方なく、半兵衛はドアを開けた。こうして、秀吉は半兵衛の心を開き、二人は友達になった。 それから、秀吉はどんなに忙しくても時間を割いて半兵衛のもとを訪れ、薬や世界中から集めた書物を持ってきたり、困ったことがあれば相談にのったりして、半兵衛を天下で最も賢い人だと評価した。半兵衛も秀吉のお人好しな性格を理解し、もし誰かに指摘されなければ、秀吉は遅かれ早かれ悪人に利用されてしまうと予見した。だが誰かに補佐されれば、秀吉の力は、天下の人を幸せにすることができると思っている。 そのため半兵衛は家から出て、秀吉を補佐することにした。またベッドで療養しなければならなくなっても、半兵衛は自分の知恵を活用して秀吉のために戦略を立てた。秀吉も半兵衛に全幅の信頼を寄せ、彼女の提案に従って何度も災いを回避していった。\n\n【その三】\nゴホン……まだ頭がぐらぐらするから、今日はもう横になりましょう。\n\n以前読み切れなかった本の続きを読むのにちょうどいいですね。\n\n何か用事ですか……？私ではなく、秀吉様が帰るのを待って彼女に言ってくださいませんか。\n\n体力が尽きました・・・少し寝ましょうか・・・少しだけ・・・\n\nえっ？秀吉様がいらっしゃるんですか！\n\nゴホゴホ！ゴホッ！ゴホッゴホゴホ……\n\n秀吉様、私は大丈夫です。病気はだいぶよくなりました。\n\n今度の外出で何があったのか、早く教えてください……ゴホン。\n\nうんうん、今回出会ったのは良い人ですね、彼女を助けたのは正しいと思います。\n\nゴホゴホ！でもその後の人は秀吉様を利用しています、気をつけて！\n\n自分に厳しく、人に寛大であれ。ゴホン、私がいなくなっても、太陽のように……\n\nなんと仰ろうと、次の合戦は……私も一緒に行きます！ゴホン！ゴホゴホ！\n\nわかりました……今回は我慢しますが、この配置を覚えておいてください。\n\nここには伏兵が設置し、ここ、そしてここも、あとはここに……ゴホン……\n\nよし、ゴホゴホ、これらを覚えれば必ず勝てます。これは十面埋伏の計です。\n\nでは、ご武運をお祈りします……\n\n秀吉様……天下を統一して、みんなを幸せにしてください……",
    "skills": null,
