    "cv": "ナユキユズ",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA1MjRfMjA1/MDAxNjg0OTA3NjM0MTQx.EkLp500GUNfVATiMqoWMDo_Jrwb8sFcOxXAr_6nCE-Ag._dbY6809jyaEv5t9t1-DGrT3aijg_aL-TtmDCU1yYsMg.JPEG/%EB%A7%88%EC%82%AC%EB%AC%B4%EB%84%A4.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "我は神に選ばれた者・光の使徒・夜と闇の終結者・伊達政宗でござる！我と共に邪悪勢力に対抗し世界を救う準備はできたか？相棒よ！",
      "ホーム画面タップ１": "相棒！我と共に灼熱の太陽を迎え、冷たい風を浴びて、星と暗月の下で、神々の神殿を目指し、運命の起源を探そう!",
      "ホーム画面タップ２": "我は二丁拳銃を持っている、１つの名は終結、もう一つの名は、破滅だよ！我は彼らで汝の死亡の挽歌を奏でてあげるわ！",
      "ホーム画面タップ３": "異世界からの勇者よ！もしかしたら汝は我の運命なのか？ならば我と血盟契約を締結し、1人になって貰おう！",
      "ホーム画面下着状態": "我は今日誤って邪悪な悪魔を封印する魔法兵器を壊してしまった! そのため、悪鬼が再び現れ、我がとんでもない罪を犯したことは分かっている！だから我は至高無上の汝様に謝罪しに来たのだ！",
      "ホーム画面下着タップ1": "誤りを知ってそれを改め得ることほど素晴らしいことはない！これは我ら「神に選ばれし者」に必要な品質だ！",
      "ホーム画面下着タップ2": "まだまだだ！もっと我にお仕置きをしてください！あなたの怒りを全て発散するまでしてください！",
      "ランクアップ": "「破滅の瞳」の力を手に入れる日が来た！",
      "覚醒": "銃口から発散したのは汝が暗闇に落ちる前に見た最後の光だ！",
      "調教道具1": "------------------------------",
      "MVP宣言": "いつか必ずこの世界は私の足元に落ちてくるのだ!",
      "プレゼント-挨拶": "我に汝の期待を語ってよい！",
      "プレゼント-感謝1": "う～ん！我は感じた、汝の心からの情熱を！",
      "プレゼント-感謝2": "汝の応援、ちゃんと我に届いたよ！",
      "プレゼント-感謝3": "この美食のためにも、絶対にこの世界を守って見せる！",
      "クローズアップ": "------------------------------",
      "スキル1": "ふふん！",
      "スキル2": "シュシュシュウ～",
      "スキル3": "爆裂しろう！",
      "奥義1": "天下～無双！",
      "奥義2": "我こそが伊達政宗！神に選ばれた人よ！",
      "死亡": "我は世界に...捨てられた...のか？"
    },
    "story": "【その一】\n伊達政宗は中二病で、自分が選ばれし者だと思うのは、 おそらく、幼いころに経験したことが原因であろう。\n\n伊達政宗の母親・義姫は、夢で隻眼の僧・満海上人が生まれ変わりたいと願っている様子を見て、縁起が良い夢で妊娠した。そのため、伊達政宗が生まれる前から、政宗は満海上人の生まれ変わりだと言われていた。そこで、輝宗は伊達政宗の誕生後、彼女に「梵天丸」の名を授けた。\n\n織田信長が霊峰比叡山を焼き払い、大暴れをした年は、伊達政宗は5歳で、ヘルペスを発症し右目が金色になったそうです。右目の異常だと皆に言われたので、彼女は眼帯をつけ始めた。それで政宗は「独眼竜」と呼ばれ始めた。右目の異常こそ、彼女が満海上人の生まれ変わりである重要な証拠になった。（満海上人も隻眼であるからだ）\n\nこうした逸話を知って、「自分は他のみんなとは違う、世界を変える大きな使命がある」と感じたそうだ。小十郎の褒め言葉と相まって、伊達政宗は自信満々になった。周りの人に「おかしい」と思われるような行動でも、いつも小十郎に褒められた。\n\n小十郎は、今の伊達政宗を作った張本人なのだ！\n\n【その二】\n彼女の右目について、小十郎にも話したことのない、今でも思い出したくない悲しい思い出があった。\n\n幼い頃、彼女は寝たきりの状態で、父親は連日祈り続けた。神様に保護されたおかげか、彼女は生き残った。ただその時から彼女の右目が金色になり、眼帯をつけて「独眼竜」と呼ばれるようになった。それだけではなく、母親も彼女のことを嫌いになり、異色な瞳を持つ彼女は醜いと思い始めた。その結果、義姫は伊達政宗への想いを11カ月下の弟・伊達小次郎にぶつけてしまった。母親の突然の態度の変化に幼い心は打ちのめされ、それ以来、彼女は劣等感や臆病さを心に抱えた。\n\nしかし、予想外だったのは、母親が彼女に毒を盛ったことだ。彼女は弟の伊達小次郎を家督に就かせるために、政宗を食事に招いて、長い間今までのことを謝り、母親が自分の過ちに気づいたと本気で思わせようとした。 しかし、政宗は腹部の激痛で一瞬で我に返り、それが油断させて殺すための幻術だったことに気付いた。\n\nなんとか生き残った伊達政宗は、失望した母親に山形城に軟禁された。「自分とは関係ない」と誰かに原因を問われるといつも母親はそう言い返した。おそらく、彼女の心の中にはまだ母親への愛が残っていたのだろうが、その愛は最後まで報われることはなかった。\n\n【その三】\n「吾は選ばれし者だ、選ばれし者の預言は間違えないんだ！」\n\n「は？……吾は信用できないと？」\n\n「可哀そうな凡人よ、あんたらには選ばれし者である我々の考えが分かるはずがない！」\n\nまたもや信用できないと言われた伊達政宗はめげることなく、「選ばれし者」としての預言を他人に語ろうとした。\n\n私の預言がこれほどまでに的中しているのに、なぜ誰も信じてくれないのだろう。私は選ばれし者として、天の意思を実践しているのだ。傍目には愚かに見えるかもしれないが、偉い人は皆、奇妙なことをするものではないのか？だから、凡人は凡人で、私の本心を理解してもらうことは望まない。私はあきらめずに、人々を救う義務を果たし続けるのだ……\n\nとは言え……さすがにこの責任は重くてこのまま一人でい続けたくはないんだ。この責任を共有できる気心の知れた相棒がいれば、深い絆で結ばれ、私の思いと本心を理解してもらうことができるのに……",
    "skills": null,
