    "story": "【その一】\n師匠に出会う前は、趙雲は難民中の一人であった。\n\nその時、趙雲がわかっていたことは、『食べ物』と『他』しかない。\n\n食べ物以外の全てが暗く見えていた。\n\n子供時代に灰色の中で生まれ、何も思い出なんてなかった。\n\n師匠に出会う前は、趙雲は知らなかった。\n\n熱々のお饅頭が、どれ程美味いか。\n\n服から、どんなに良い匂いがするか。\n\n人とは、生と死の他にも、性別があるということ。\n\n先輩たちが趙雲を恐れているのは、彼女が武芸の習得が早いことでも、門下生の中で唯一の女の子だということでも、師匠からの寵愛を一身に受けていることでもない。\n\nその理由は、彼女の頭の中には『性別』という概念が存在しないことだ。\n\n昔、趙雲が師匠に山の中に連れ出してもらったときに、彼女は先輩達の使っているお風呂に突っ込んでしまったが、そのまま着替えて皆と一緒に入ろうとした。\n\n幸い、先輩達は言い訳を探して彼女を止めることができ、同じ女性として趙雲に性別知識を教えるという大任を師匠に託した。\n\nしかし、師匠も自分でもどう教えればいいのかわからなかったのか、女性用風呂場ではいつも『抱きついてスリスリするんじゃない！』と、師匠の叫び声が聞こえている。\n\nだが、師匠の威厳と武芸のためにも、男子達は全員黙り込むしかなかった。\n\n【その二】\n外出の仕入れの他に、趙雲は師匠以外の女性をあまり見たことがない。\n\nそして趙雲の目によると、師匠は他の女性と大いなる違いがあった。\n\n外の女の子は皆綺麗な衣服を身に着けているが、師匠の服は清潔だが、男性のような服に近い。\n\nなので、外にいる女の子を見る度に、趙雲はいつもスカートを引いて触ってみたかった。\n\n彼女達の体は師匠と同じく滑々で…柔らかいかもしれない…だけど、彼女は師匠からダメだと聞いていたのでずっと我慢していた。\n\nこの日、趙雲は仕入れの際に、とある山賊が二人の少女を襲っているところを目撃した。\n\nそこで彼女は勇ましく山賊の集団に突進し、全て追い払った。\n\nその後、助かった少女達に山賊は村の他の子たちも捕えていると聞いた途端、趙雲は村から馬を借りて、夜のとばりに山賊の本丸を奇襲した。\n\n7度7回繰り返し、なんと6名の少女を救出した上に、一箱の略奪された財物を見つけ出した。\n\nこうして、趙雲は少女たちの英雄となった。\n\n女の子たちは彼女の周りを囲んで、彼女の勇武を歌ったりし、そして趙雲は村を離れる前に彼女たちに大きなハグをした。\n\n趙雲はようやく女の子に抱き着くことができた。柔らかいなぁ！女の子はいいなぁ！\n\n【その三】\n門下から離れてもう二ヶ月か…僕は師匠に会いたいなぁ！師匠と一緒にお風呂入りたいなぁ！師匠はいつもいい匂いするし、体が細いのに、だきついたっらやわらかいし！\n\nあっそうねぇ、孔明様の肌もいいねぇ！だが、なんというか…気安く触ったら、怖い話になるんだ…\n\nうっ…もしかして、妹ちゃんだけがいちゃいちゃするのが好きかい？前に可愛い迷子を助かったら、可愛いちゃんは抱きさせたり、『ちゅう』っとキスされたの！えへへ～もっともっと、可愛い子を知りたいなぁ！\n\nそう言えば、師匠から教われたの、僕は女の子だから、もっと女の子と一緒に遊べるべきって。うんうん！僕も、女の子達ともっと知りたいよね！\n\n…なんか…凄く魅力的な君主お姉さんと聞いたけど…一面に見られると、引き寄せたっり、体の一部が石化されたりとっか…うっ…彼女はまさか　魔女なの？！",
