    "role": "噴霧攻撃、鉄血宰相",
    "cv": "菜月なこ",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA1MjRfNzIg/MDAxNjg0ODk3NTczNjQz.LsbpzqU4KRwRtLIpYBqq5asgBe4IW4fe97pJzzB6zAsg.hwKtyMFDB-itXPz47RVP2NtE41Z3ram3OBpC7fqx-uIg.PNG/%EB%B9%84%EC%8A%A4%EB%A7%88%EB%A5%B4%ED%81%AC.png?type=w1678",
