    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "よし、スケジュール通りです。ビスマルク、ただいま参りました。何かありましたら、前もってスケジュール帳に記録しておきます。",
      "メインページでタップ1": "何かご用でしょうか？急ぎの用事でなければ、14分51秒後に空いているので、その際にまたご相談ください。",
      "メインページでタップ２": "ん？なぜそんな変な目で私のスケジュール帳をじっと見ているんですか？これは私の全てです。これがないと、非常に困ります。",
      "メインページでタップ３": "よし、今日の日程は終了しました。就寝の前にあと20分の休憩時間があるので、何かしましょうか？",
      "メインページでタップA1": "あの…この処理を手伝っていただけますか…？予定外のものの処理は得意ではないのですよ…",
      "メインページでタップ-下着1": "こ…こんなことは予定に入っていませんよ！！！！",
      "メインページでタップ-下着2": "この感じ…っ！嫌だ、もう一生忘れられない、ううぅ…！",
      "星アップ": "また強くなりました、いいですね、すべて計画通りです。",
      "覚醒": "身体能力が大幅に上がったと？これは少々予想以上ですね…",
      "親密アイテム1": "早く出してくださいよ！あっ、もっと奥に入っちゃう…っ！",
      "親密アイテム2": "こんなの全然触れてないじゃないですか…！道具なんて使ってないで、直接手でやってくれませんか？お願いですから早くしてください…もうダメ…っ！",
      "MVP宣言": "この段階の戦い終了です、次の段階に参ります。",
      "スキル1": "邪魔です！",
      "スキル2": "どいて！",
      "奥義1": "ドラゴンとの力比べだ！",
      "奥義2": "空の星になりなさい！"
    },
    "story": "【その一】\nビスマルクがまだ彼女の予定表と「関連」されていなかったとき、彼女はかなり自由な生活を送っていた。\n\n当時のビスマルクは、毎日の通学に剣や猟犬、時にはポニーを携えていた。\n\n遅刻、早退、授業中に居眠りすることが多く、一方で宿題もやらずに、クラスメイトと口論や決闘をすることがビスマルクの「普通の日常」だった。\n\nしかし先生がビスマルクの両親と彼女について面談しようとしたところ、「予約が必要」と言われ、すでに翌年の秋に予定が入っているとのこと。おかげでビスマルクは、人生最後の、予定表のない時間を楽しく過ごすことができた。\n\n長い間待っていた先生は、ようやく予定通りに翌年の秋にビスマルクの両親と会うことができ、ビスマルクの「悪事」を説明した。\n\nこのように、ビスマルクはこの保守的な古き貴族の家系によって、厳しく細かく矯正を受けることとなった。\n\n父親と母親は自分の経験をビスマルクに伝授し、ビスマルクが毎日やっても良いとされることと、それに対応する報酬と罰則を定め、予定表を作成した。\n\nビスマルクはそれに従わなければならなかった。\n\n家庭からのプレッシャーによって、ビスマルクは予定表通りに行動するようになった。\n\n両親の真面目な性格の遺伝もあってか、ビスマルクはとても順調に守ることができた。\n\n【その二】\n予定表のおかげで、ビスマルクの学力は飛躍的に向上した。\n\n今まで先生たちからダメな学生と呼ばれていたビスマルクは、今となっては人品学業共に優れている模範となった。\n\nしかし、ビスマルクと衝突していた学生たちは、この機にビスマルクに仕返しをしようと考えた。\n\nそのため、彼らはビスマルクの予定表を捨て、これがないと生きていけない馬鹿だと嘲笑った。\n\nビスマルクは彼らを叩きのめようと思ったが、これは自分の予定にないことだと思い、必死に我慢した。\n\nその日、予定表を持っていなかったビスマルクはいつも通りに授業に出席し、講義を聞き、小テストで良い成績を取り、そしていつも通りに帰宅することができた。\n\n夜になって疲れて帰ってきた両親が悲しそうな口調でビスマルクに「どうしておばあさんの薬を届けに行かなかったのか」と聞いてきた。\n\nそしてビスマルクはやっと、毎月のこの日にはルーダー博士の家に薬を取りに行き、隣町のおばあさんに届けていたことを思い出した。 \n\nしかし、今ではもう彼女の祖母はいなくなった。\n\nもうすでに手遅れだった。\n\nビスマルクは新たに予定表を用意し、罪滅ぼしのように、すべてのことを逐一細かく記載するようになった。\n\n彼女はもう予定表を手放すことができずに、予定表がないと何もできなくなった。\n\n【その三】\nうんうん、計算によって、インクと種類の間の距離がちょうどよく、室内の明るさもほぼ完璧と言える、でも･･･\n\n少し騒音が聞こえるけど、まあ想定される許容範囲内、よし！予定表通りに、完璧な仕事を始めよう！\n\n･･････え? これ？ 上司の･･･メモ書き？ メッセージ？「また素晴らしい新アイデアを思いついたから、明日会議を開いて話し合おう！\n\nほほ、頼むよ、ビスマルクちん。――フレデリックちんより\"\n\nああああ、「ちん」じゃないわよ。\n\nなんて頼りにならない上司なんだろう！\n\n毎日毎日、新しい企画に変えるのはいいとして！\n\nなぜ会議なんて1週間前に言わないんだあああああ！\n\n･･･私が昇進したら、こいつら全員に完璧な日程予定を組んであげなきゃああああああ――",
    "skills": null,
