    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA4MTZfOTgg/MDAxNjkyMTY4MzM4OTEw.fvWMLFr7UM9UGIAAvsqSZUtb1STm5FI_Y3mFoPJKqm0g.baZ6lLPRDg72VMhig74O3IEghe5XDTY3uUBqlKHoTUwg.JPEG/%ED%94%84%EB%9E%91%EC%BC%84%EC%8A%88%ED%83%80%EC%9D%B8.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
