    "story": "【その一】\n科学者フランケンシュタインが死んだ友人をもとに作った人造人間、コードネームMR42は、すべての個体の中で最も成功したものであった。 彼女に読み書きを教え、死んだ友人の言動を学ばせることで、言わば魂を蘇らせようとした。 しかし、フランケンシュタインはMR42との接触するうちに、この子が自分の望んだ友人の復活のための入れ物ではなく、新しい命であることに恐怖を感じた。つまり、最も成功したはずの個体が、まさに彼らの妄想を打ち砕く諸刃の剣であったのだ。「生き返った者は、本当に記憶の中のあの人なのか？」-- 神々は、神々に挑もうとする凡人たちに、最も絶望的な嘲笑を降り注いだ。\n\n【その二】\nMR42は、母、フランケンシュタインのことが大好きです。母はいつもおいしい食べ物やおもちゃをくれますし、面白い本もたくさん読んでくれます。 母は「母」と呼ばれるのを嫌がっていますが、MR42は母と呼ぶことにこだわっています。なぜなら、母は、本の中で「母」と呼ばれている生き物と全く同じだからです！ ローランドおじさんにも母、リリーおばさんにも母、母にも母がいます、だからMR42も母が欲しいのです！ 本には「母は世界一」と書いてありますから、あとで母に会えることを考えただけで、ナイフが降ってきても、MR42は全然怖くありません！ ねえ！ 母に話したら褒めてくれるでしょうか！\n\n【その三】\n茶々に引き取られた後、フランケンシュタインという名前を与えられた彼女は、茶々の家に住み着き、茶々の妹となった。 記憶をフォーマットされたせいか、フランケンシュタインは過去の記憶を失っているだけでなく、言語モジュールも少し損傷していた。しかし、幸いにも茶々やみんながそばにいたおかげで、フランケンシュタインは何の不自由も感じなかった。 茶々に無理やり引っ張られて外に遊びに行く以外には、フランケンシュタインは部屋にこもって、歌うロボットカエルや歩く親指兵などの発明品を作るのが好きだ。だが、さまざまな理由から、茶々の家には不気味な科学者が住んでいて、秘密の邪悪な実験をしているという噂が流れているようだ。",
