    "story": "【その一】\n農家出身の武蔵は、村の人々と同じように素朴で楽観的で心が優しいが、生まれつき怪力を持っていた。小さい頃から、村の農作業が終わらなかったり、獣が出没したり、近所でトラブルがあったりすると、武蔵がその力で解決してきた。そのため武蔵は村の英雄と呼ばれ、心にはそれなりの責任感が芽生えていた。ある日、隣の村が邪竜に襲われたという知らせが伝わると、村のみんなは怯えて武蔵に助けを求めた。しかし、村を出たことのない武蔵は家を出た途端道に迷ってしまい、山を半日ほど彷徨ってからたどり着いた頃には、隣の村はもう廃墟になっていた。また何日か迷った末にやっと家に戻ると、自分の村の人はみんな彼女が帰ってこないと思って、とっくに逃げ出してしまっていた。こうして武蔵は自分の運命を知った。このまま家族が見つからなければいっそのこと邪竜を探しに行けばいい、どうせ邪竜を撃退しなければいつまでも逃げ続けるだろうから。彼女は荷物をまとめ、邪竜討伐軍の軍団を探している。他人と一緒にいれば、二度と道に迷うことはないだろうから。\n\n【その二】\n大都市は武蔵が思っていたほど素敵なところではなかった。彼女はまだ功績が何もなかったため、足軽から始めなければならないと言われたのだ。この仕組みは、邪竜を討伐してから里に帰って農業をしようと思っていた武蔵を困らせた。貯金が底をつきそうになったところで佐々木小次郎に出会い、決闘を申し込まれた。わずかな賞金目当てで応じた武蔵だったが、思いもよらず、全力で両手の刀を振らなければないほど、小次郎が強かった。やっとの思いで勝利した瞬間、武蔵は疲れ、さらにお腹が空いて倒れてしまった。彼女が再び目を覚ますと、小次郎の膝枕に横たわっていた。小次郎に武蔵が二刀流を使う姿がかっこよかったと言われ、武蔵は逃げようとしたが、小次郎が作ったおいしそうな手料理の香りを嗅いでとどまった。2人は一緒に食事をして長話をしたが、小次郎は結婚を迫られてまともな人たちと決裂し、今も帰る場所がないことがわかった。武蔵はそれを聞いて似たような境遇にあると感じて同情の気持ちが生まれ、一緒に行動しようという誘いに同意した。しかし、小次郎は一緒に戦隊を作ることに同意したと思ったようで、武蔵と天下一の敵役戦隊を結成すると宣言した。武蔵は敵役になろうとは思っていなかったが、時間と共に一緒にいることに慣れてしまった。それ以降武蔵がどんなに道に迷っても、小次郎が作る夕食の香りを嗅げば戻ってくることができ、小次郎も全然責めることはなく、さらに「日が暮れるまでは遅刻ではないよ」と言ってくれた。\n\n【その三】\nなんだかんだと聞かれたら！\n\n遠慮なくいただきます……\n\nあれ、間違ったか？\n\n小次郎、最初のセリフはなんだっけ。\n\n小次郎？あれ？さっきまで隣にいたのに？\n\n前方に道がなくなったぞ、ああ、また道に迷ったようだ。\n\n大丈夫だ。それなら回り込めばいい。もっと歩いていればきっと見つかる。\n\nあれ？あそこにいるのは山賊だ、村を襲ってる！\n\n日本の平和を守るため、そして……いやもうどうでもいい、とにかく、参る！\n\nああ、山賊がたくさん…囲まれてしまったのか。では、私の二刀流をご覧あれ！\n\nふぅ、一件落着。村人たちは大丈夫か。\n\nへへへ、どういたしまして。ところで、私たちの戦隊に参加しないか？一緒に邪神に立ち向かおうじゃないか。\n\n敵役戦隊、ロックチームだ！\n\nどうして逃げるんだ?お前たちが思ってるような敵役じゃないぞ！\n\nまた失敗だ…お腹空いた…あれ？この香りは！\n\n小次郎が作る夕飯の香りだ！帰る道が分かったぞ！\n\n小次郎~今帰るから～待っててくれ～！",
