    "story": "【その一】\nメディアは幼い頃から寵愛を受けていて、人々は彼女を甘やかし、好きなことを好きなようにやらせていた。\n\nある日庭の花を鑑賞していたメディアは、王国の財宝を盗みに来た青年に騙され、彼の冒険話を信用して、一緒に財宝をもって城壁の外にある未知なる世界へと逃げ出してしまった。\n\nしかし青年は脱出に成功した直後、約束を裏切り、少女を一人荒野に置き去りにした。騙されたメディアは怒りのあまり、初めて自分の中に魔法の力を感じ、やがてこの嘘だらけの男を見つけた。男に自業自得の罰を下し、財宝を取り戻したメディアは、放浪の旅を始めた。\n\n【その二】\n魔龍姫の軍勢が迫り来る中、世の中には別れを余儀なくされるカップルも多く、また生き残るために相手を裏切る悪人も多い。メディアは、助けるべき者を助け、罰するべき者を罰するために全力を尽くしたいと考えている。しかし、メディアは自分がしばしば悪党に利用され、間違った人を助けてしまっていることに気が付いた。またもや悪人に利用された後、彼女はついに決断し、その杖を悪人の頭に叩きつけた。彼女はようやく、恋人間の争いのほとんどが裏切りから生じているという事実に気づいたのだ。そして、心の中に裏切りを抱く男女をすべて排除すれば、純粋な愛だけが存在する時代を切り開くことができ、自分のような悲劇が二度と起きないようにすることができると考えた。その日から、浮気者を恐怖に陥れる名前が各大都市に広まっていった。\n\n【その三】\n...メディアはただ正義の使者となっただけで、メディアという名を汚しているのではないか？\n\nもちろん、彼女は恋人を裏切る「クズ」を排除している。\n\nしかし、誰が裏切りを判定するのだろうか？メディアに「クズ」と認定されたら最後、彼女はあらゆる手を使ってあなたに「罪」を自白させるだろう。さもないと、彼女は世界の果てまで追いかけてくる。\n\nたとえその「罪」があなた自身の意志によるものでなかったとしても、多くの誤解があったとしても、\n\n彼女はただ、「自業自得よ。」と言うだろう。\n\n「どんな理由にせよ、恋人を裏切った者は、この苦しみを受けるべし！」\n\n「奈落に堕ちるがいい！」",
