    "story": "【その一】\n中州毛利家の子供だけど、毛利元就の生活はいつも貧しかった。親と兄上はこの世に早い去ったので、まだ幼い元就が家主を継ぐされ、妹の世話と領土の責任が肩に載せられた。周辺大名の企みを恐れずに、賢い彼女が精妙の技を使い、兵士より数倍の敵を追い払った。だが、どう優れた戦略でも人の心が読めぬ、家臣が次々と敵に買収されて、元就と妹たちがとうとう家を失い、流浪の生活が始まった。彼女たちがいつでも居場所がなく上に、衣食も得られない、更に親族から冷たい態度をされた。でも元就と妹たちがそのすべたを耐えた。姉として、元就はいつも精一杯で妹たちを育てて、彼女達に全てを捧げるが、元就はひっそりと復讐の種火を心に刻むーー彼女が決まった、いつか必ず代々相伝の領地が奪い返すのだ。その暗くて鬱々の生活に、妹たちの寄り添いは元就として一番の慰めになった。\n\n【その二】\n元就は一日でも領地を奪い返すことが忘れなかった。彼女は幼い妹たちを世話しながら、周りの諸国に助けを求めた。色々な目的のため、数がある隣国はその声を答えただが、その代わりに、彼らが残酷な条件を出された――元就の妹たちが人質になり、各国の都心に残されるのだ。あまりの怒りに目をつぶった元就は、彼らの要求を応じた。\n\nこうして、妹たちを引き換えとした援軍を率い、才能と謀略を基づいて、元就は早速領地を奪い返した、数年を掛けて流亡した『乞食の若殿』はようやく彼女こそ相応しい位置に戻った。\n\nただし、元就は空っぽなホールに見かけて、彼女が猛然と気づいた、自分の周りにもう誰もいないこと。こんな孤独の前に、一切の争いも成功も、元の価値が失くされた。\n\nその後、他国の同盟軍は元就を援助した後に、約束の道理に離れず、むしろ毛利家の領土を企んで分け取りつもりだ。しかし、元就はもう争いの気力がなくなった。強盗達に毛利屋敷を燃やした時、元就は既に城外の山に逃げ出した。焔と煙を眺めた彼女があまり心残りがない、ただただ、昔のように流浪の生活に戻っただけなんだ。\n\n何処が違いがあると言うなら、今度こそ、自分は一人きりだっと、思いをついた彼女が涙を止まらないだ。\n\n【その三】\nお姉ちゃんはねぇ、お世話するのがとっても上手なの！ご飯を炊くことでも、服を縫うことでも、看病も悪い奴を祓うでも、ふふっお姉ちゃんは全部全部上手なの。うっ…別に世話をするのが好きっとか、あえて世話をするじゃなくって…なんか、体が勝手にさせられたというべきか、気がついたら、もう出来るようになったのぅ。ふふっ、これは多分お姉ちゃんとしてこその天賦と天性だったかなぁ！ふふ。\n\n私は皆が頼れるお姉ちゃんだもの！こんなにたくさんの妹たちなのに、一人一人の好きな食べ物や、おもちゃや、好きな事まで、私は全部覚えているのよ！誕生日なんて当然のこと、何より今日はーー\n\nあっ…ああ、妹…私の妹たちが…ごめなさい…ごめなさいね…私、私は最低最悪のお姉ちゃんだった！\n\n領土を、領土を奪い返すことが一番大事なことを見つめて、ずっと寄り添う家族が逆に見えなくって…家族がいる場所こそ、私が守らなければならない場所なのに…\n\nああっごめんなさい…ごめなさい...私のことを許して...私、私はもう一人になりたくない、私は...家族が欲しかった...",
