    "dialogues": {
      "初めて頭を撫でる": "うん？何か用か？",
      "胸を触っちゃダメよ！": "ダメだよ。少なくとも、今はね。",
      "脚を触っちゃダメよ！": "運動こそが健康的な美脚をたもつんだ。ねえ、今度は一緒にやろうか！",
      "結婚する時に獲得": "きょろきょろするな、こういうときは私を見るものだろ！ふん、ハッピーバレンタイン！",
      "着衣状態でスカートをめくる": "おい、ちゃんとレディーの気持ちを考えろ！空気の読めない奴だな！",
      "着衣状態でドレスの帯を引っ張る": "やんちゃ坊主だな～、でも今はその時じゃないだろ？",
      "パンツの帯を下に引っ張る": "その目つき、ケモノみたいだな…ふふ…",
      "着衣状態で水鉄砲をタップする": "あっ！なっ、何するんだ！まったく、これはもう脱ぐしかないじゃないか。",
      "胸をタップする1": "ゲームをしないか？え？何か賭けようって？…ふふん……",
      "胸をタップする2": "私の体温が残ったコインが欲しいのか？",
      "胸をタップする3": "うわっ！寒いっ―――あ、落ちちゃった！",
      "頭をタップする": "う～ん、潮風が気持ちいいな！",
      "手をタップする": "ははっ、海の上で飲むビールは格別だな！",
      "脚をタップする": "あははっ、誰かさんの目が飛び出そうだ。",
      "花嫁の間の特写": "今夜の私は君を誘惑できるかな？ダーリン。",
      "自宅で彼女を寵愛する時": "はっ、はぁ…もっと、ほしい…。",
      "限定-頭をタップする": "チュッ。愛してるよ、ダーリン。",
      "限定-体をタップする": "こいつ、私が恥ずかしがる姿を見たいだけか？"
    },
    "story": "【その一】\nレオニダスの子供の頃、両親は代々受け継がれてきた宝物を守る為に亡くなり、レオニダスは最後の一族として運命を全うするためにその宝物を持って一人で山奥に逃げ込んだ。最初は普通の少女だったので、危険な無人の山の中で生き延びようとするのはまるで賭けのようだった。側溝の水が飲めるかどうか、色のついたキノコに毒はないかどうか、木の槍がウサギに当たるかどうか、通りすがりのヒグマに見つからないかどうか……これらの賭けに、彼女は残念ながら運に恵まれなかった。しかし、彼女は常人の何十倍も努力で鍛え上げ、どんなに失敗してもその強靭な肉体を崩さなかった。そしてついに、城内の少女のように化粧をすることができる年齢になったレオニダスは、素手で狼を倒すことができ、使命を果たした彼女は、すでに別世界となっていた城に戻ることができたのだった。自分より背の高い男を次々と打ちのめす彼女の後ろには、城内の若者たちが集まり始め、彼女を「姉貴」と呼び、若い兄たちが食事や宿を手配して貢ぎ物をした。だが、レオニダスはこのような人間関係がとても苦手で、これらの子分たちを追い出そうと、あらゆる手を尽くした。\n\n【その二】\nいつしか一味はスパルタと呼ばれるようになった。レオニダスはギャンブルをする時にこの言葉を叫ぶのが好きで、彼女はそれを元に自分なりのスパルタ訓練法を作った。その訓練法は自身の山中での経験だけを模した厳しい訓練で、その訓練を全部やり遂げた者だけが残れるとレオニダスは言った。驚いたことに、300人の兵士が訓練に合格したので、レオニダスは彼らの入隊を認め、スパルタ300人と呼ばれるようになった。長年、山で暮らしてきたレオニダスは、人間のことをよく知らない。ただ、ギャンブルの負けは取り返しがつかない、約束は守らなければならない、人からの助けは返さなければならない、ということだけは分かっていた。また、子分の信頼に応えるため、彼女は安心できるサポートをしている。一味が財政難に陥ったとき、レオニダスにお金を求めたところ、彼女は300ゴールドで一挙に20万ゴールドを勝っていたことがあり、一時はカジノ界の伝説となっていた。それ以来、一味で悪いことをする者はいなくなり、レオニダスは皆を集めて物資を運び、家を建て、護衛をし、山賊と戦い、ちゃんとした団体にしていった。しかし、社内にあるオープンカジノで、レオニダスは大小の機会問わず必ず賭けに行く際一度も勝つことはなかったが、「カジノで負けたお金は、人生の大事な時のための運を蓄えているということ」と、悪いことではないと言った。\n\n【その三】\nよいしょ、よいしょ……やっぱり運動しなきゃ体がリラックスできないな。\n\nおや！水平バーが壊れちゃった、また無理をしてしまったかな。\n\nやばい！あいつらがまたここにきたのか！どうしよう、ここじゃ隠れる場所がない。\n\nお前ら毎日私を追いかけてくるなよ、何かやることを探してきな！\n\n骨折はまだ治していないのか？それとお前、告白は成功したのか？また来ない奴がいる、また腹の調子が悪くなったのか……ったく、なんでどいつもこいつも心配をかけるんだよ！\n\nやっぱ解散してまた一人で山へ行こうかな！\n\nまあまあ冗談だよ、山は城内ほど楽しくないから、遊ぶ前に働かないとね。街は道路を作る人が必要だから、そこでお金を稼げばいいんだよ。\n\nふー、やったー、うまくいったな、給料も悪くない。\n\nさて……久しぶりのギャンブルの時間だ、誰か一緒に来ないか？\n\n何？昨日行ったばっかりだって？それはもう久しぶりだろう！\n\n負けたらどうするって？大丈夫だよ、今日の負けは明日の運を貯めるためだから、昨日ずいぶん負けたからこそ今日は順調だよ！\n\nさあ、始めよう！私はこっちにする……何と？負けたか。\n\n大丈夫、私はもうはっきり見えたから！今度はこっちだ！オールインだ！\n\nこい！こい！こい！スパルタ！",
    "skills": null,
