    "dialogues": {
      "初めて頭を撫でる": "無礼者！ぶっ殺すぞ！",
      "胸の前の紐を引いてはいけません": "ふん！俺様はそんな軽い女じゃねえ！",
      "ストッキングを脱いではいけません": "勝手に触ったらその手を切るぞ。",
      "結婚する時に獲得": "なにを…ボーっとしてるんだ？こっちにこい！",
      "太腿を引っ張る": "ほお？意外といい度胸してるじゃねえか。",
      "靴を脱いで足を揺り動かす": "俺様の美しい足を堪能しな！",
      "太腿を触る": "ふん…俺様の太ももに惚れたのか？",
      "足を触って照れさせる": "観賞タイムは終わりだ！",
      "胸元をゆらゆらさせる": "今日限り、思う存分見せてやろう！お前だけだからな！",
      "胸元の糸をタップする": "おい！何を考えているんだ？",
      "胸元の糸を引っ張る": "俺様は、気が短い男は嫌いだ！",
      "フリンジを整理する": "こういうのが、俺様より魅力的なのか？",
      "足を組む": "ちょっと脚をマッサージしてくれないか？あ、な、た…。",
      "胸元を触る": "あ…この感じ…なんか…おかしくなりそうだ…",
      "右足の靴を引っ張る": "俺様のハイヒールに何をするつもりだ？",
      "左足の靴を引っ張る": "俺様のハイヒールをなくすんじゃないぞ！",
      "右足のストッキングを引っ張る": "もう少しだったのにな…",
      "左足のストッキングを引っ張る": "おや…こうなったら…",
      "下着を引っ張る": "軽薄すぎだ、お前死にたいのか？！",
      "足を触る": "その間違った考えは今すぐ捨てろ！",
      "手を触る": "俺様と手を繋ぎたいのか？ふふ…",
      "花嫁の間の特写": "うん…（喘ぎ）ん…ずっと待っていたんだぞ…",
      "自宅で彼女を寵愛する時": "あっ（喘ぎ）…この気持ちは一体…"
    },
