    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzEyMjhfMjIw/MDAxNzAzNzQ5NDg0NTQy.jGGUjW4z7mLL_s2t52FElL1LnnVTzEu4socmsYdR4mog.yA_femCUTASVl3RIEhLvam_8nftjzzQiiCE863EUt-wg.PNG/%EC%A0%9C%EA%B0%88%EA%B3%B5%EB%AA%85-%EC%8B%A0%EB%B6%80.png?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "初めて頭を撫でる": "なに？寂しいの？…ふふっ！",
      "胸を触っちゃダメよ！": "だーめ！まだそういう関係じゃない、でしょ？",
      "脚を触っちゃダメよ！": "運動不足気味だけど…スキンケアは欠かしてないよ。",
      "結婚する時に獲得": "ふふっ！こうやってれば、ご褒美もらえるんでしょ？城主様も遠慮せずにくれてもいいんだよ？",
      "頭をタップする": "あ～いい感じ…城主様の手は魔法の手なの？侮れない…",
      "着衣状態でスカートをめくる": "えへへ、どうかな？このドレスは特別な生地でできてるの。いざ、っていうときのためにね。",
      "脱衣状態でタオルをめくる": "ふふふ、城主様が考えてることぐらいお見通しだよ？…早く返してよね、風邪ひいちゃったら、責任とってもらうよ！",
      "着衣状態でストッキングをスライドする": "あら、せっかちな城主様も、嫌いじゃないよ？",
      "脱衣状態で精油を塗る　1（限定）": "ふふっ！いいね、そこ、そこ！",
      "脱衣状態で精油を塗る　2（限定）": "あ、あは…ちょ、ちょっとくすぐったいって…",
      "脱衣状態で精油を塗る　3（限定）": "ああ～…癒されるぅ…",
      "脱衣状態で氷をスライドする": "ちょ、もう、気を付けてよ。…また部屋を散らかす気？",
      "着衣状態でお香をタップする": "文献によると、このお香は気分を高める効果があるみたい。城主様は…どう？気分、上がってきた？",
      "脱衣状態でお香をタップする": "え？もう終わっちゃうの？…お香、まだまだあるんだけれど…",
      "脱衣状態で精油瓶をタップする‐始まる": "ちょっと恥ずかしい…けど、これも身体のため、仕方ないよね。",
      "脱衣状態で精油瓶をタップする‐終わる": "いいね、ありがとう。…城主様も、楽しんでるね～…",
      "精油状態で体をタップする‐驚く": "ひゃっ！ご、ごめん、そこ弱くって…",
      "精油状態で体をタップする‐照れる": "う～ん…そう、そこ…もうちょっと強く…",
      "精油状態で体をタップする―断る": "あはは！ちょっと！やめてよ、くすぐったいって！",
      "太ももをタップする": "あうう、私の子供っぽいところを見せるのは、城主様だけだからね…",
      "手をタップする": "ね、ご褒美はいつくれるの？",
      "胸をタップする": "そこが好きなの？…じゃあ、もっと磨きをかけなきゃ。",
      "おしりをタップする": "城主様、ちょっとがっつきすぎだって…ふふふ！",
      "着衣状態で背中をタップする": "この書物を読めば、城主様のことは何でも分かっちゃうよ？…ね～ぇ、何が、知りたい？あんなこと？こんなこと？",
      "脱衣状態で背中をタップする": "さぁ、それを全身に塗ってくれる？もっと磨きをかけなくっちゃ。",
      "花嫁の間の特写": "あ、また変なこと考えてるでしょ…ふふっ！",
      "自宅で彼女を寵愛する時": "あー気持ちいい……ずっと、城主様にこうしてもらいたいな…",
      "頭をタップする（限定）": "城主様、この姿をあなただけに見せてあげる……その代わり、満足するまで付き合ってね。",
      "パンツを引っ張る（限定）": "も、もう！ちょっと待ってって、せかさないでよ。…さ、ろうそく消して、ゆっくり…ね？"
    },
