      "脚を触っちゃダメよ！": "そ...そこはダメです！",
      "結婚する時に獲得": "あれ...こんな姿で見られちゃいました....本当に...ああ！",
      "頭を撫でる": "うん...気持ちよかったです。続けても...いいんですか？",
      "着衣状態でスカートをめくる": "急...急にどうしたん...あっ！",
      "脱衣状態でスカートをめくる": "うわっ！なん、何でもないです！",
      "脱衣状態でパンツを引っ張る": "ダ、ダメ、こんなの絶対ダメ！",
      "脱衣状態で太ももを引っ張る": "うう...おやめください、痛い...です...",
      "頭をタップする": "あら、団子ですね！美味しい！...あれ！？…ダイエットしてるの忘れちゃってました...うぅ...",
      "太ももをタップする": "ねぇ...見ませんか？私の...",
