      "お腹をタップする": "うっはは...今夜、お腹いっぱいになりましたね！へへ",
      "着衣状態で4秒間頭を撫でる": "...うぅ...麻婆豆腐...黄金チャーハン...もう食べきれませんよ…",
      "脱衣状態で胸をタップする": "ご主人様、家康がおもてなししましょうか？",
      "着衣状態で胸をタップする": "ちょっと暑いですね。どうして部屋が急に暑くなったんでしょう？",
      "脱衣状態で脱いだ服をタップする": "や、やっぱり服を着た方がいいんですね！うぅ！",
      "花嫁の間の特写": "ご、いっ、しょ、で、す、か？...ご主人様！",
      "自宅で彼女を寵愛する時": "う、嬉しい！ご主人様！はあ～"
