      "着衣状態でリボンベルトを引っ張る": "しょうがないね、ちょっとだけ...見せてやろう...",
      "着衣状態でスカートをめくる": "ヤダ！今回は......見ちゃダメ！",
      "カバンのファスナーを引く": "勝手に触らないでね、この子は危ないんだよ、大金を払ってやっと手に入れたんだ。",
