      "脱衣状態で服をタップする": "えっ！？もう終わり...いや、別に変なことなんか考えてないよ！",
      "着衣状態で太ももをタップする": "ちょっと蒸し暑いから涼みたいんだね！",
      "脱衣状態で太ももをタップする": "赤ちゃんみたいに、ここで横になってみる？無料だよ～",
      "脱衣状態で胸をタップする": "うぅ...触らないでよ、そこは敏感なの...",
      "着衣状態で胸をタップする": "城主様...あんたも...あの...濡れてるの？",
      "着衣状態で頭をタップする　-成功": "えへへ、俺の新しい術を拝見するがよい！秘技・大召喚術！ひひー、どう～すごいだろう！",
      "着衣状態で頭をタップする　-失敗": "えへへ、俺の新しい術を拝見するがよい！秘技・大召喚術！あーあ、また失敗なの...",
      "着衣状態で頭をタップする　-大失敗": "えへへ、俺の新しい術を拝見するがよい！秘技・大召喚術！えっ！？...だっ大失敗！",
      "脱衣状態で頭をタップする": "う...、術なんかもうやらないよ、失敗したら、また、見られちゃうかも...",
      "脱衣状態でパンツをタップする": "はあ...ダメ...また変になっちゃう…",
      "花嫁の間の特写": "城主様、くノ一の必修科目って知ってる？",
      "自宅で彼女を寵愛する時": "んあ...たくさんのお金を...見た気がする...",
      "限定-腕とお腹をタップする": "え？城主様も一人なの？そんならこっちにおいでよ？夜はまだ長いから、一人じゃちょっと寂しいんだ...",
      "限定-胸をタップする": "いっ、いきなり触らないでよ、びっくりした...まあ、好きなら優しく...してね..."
